INSERT INTO public.bncc_skills (code, slug, description, grade_level, subject)
VALUES
  ('EF01CI01', 'ef01ci01', 'Comparar características de diferentes materiais presentes em objetos de uso cotidiano, discutindo sua origem, os modos como são descartados e como podem ser usados de forma mais consciente.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CI02', 'ef01ci02', 'Localizar, nomear e representar graficamente (por meio de desenhos) partes do corpo humano e explicar suas funções.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CI03', 'ef01ci03', 'Discutir as razões pelas quais os hábitos de higiene do corpo (lavar as mãos antes de comer, escovar os dentes, limpar os olhos, o nariz e as orelhas etc.) são necessários para a manutenção da saúde.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CI04', 'ef01ci04', 'Comparar características físicas entre os colegas, reconhecendo a diversidade e a importância da valorização, do acolhimento e do respeito às diferenças.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CI05', 'ef01ci05', 'Identificar e nomear diferentes escalas de tempo: os períodos diários (manhã, tarde, noite) e a sucessão de dias, semanas, meses e anos.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CI06', 'ef01ci06', 'Selecionar exemplos de como a sucessão de dias e noites orienta o ritmo de atividades diárias de seres humanos e de outros seres vivos.', '1º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF01CO01', 'ef01co01', 'Organizar objetos físicos ou digitais considerando diferentes características para esta organização, explicitando semelhanças (padrões) e diferenças.', '1º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF01CO02', 'ef01co02', 'Identificar e seguir sequências de passos aplicados no dia a dia para resolver problemas.', '1º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF01CO03', 'ef01co03', 'Reorganizar e criar sequências de passos em meios físicos ou digitais, relacionando essas sequências à palavra ‘Algoritmos’.', '1º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF01CO04', 'ef01co04', 'Reconhecer o que é a informação, que ela pode ser armazenada, transmitida como mensagem por diversos meios e descrita em várias linguagens.', '1º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF01CO05', 'ef01co05', 'Representar informação usando diferentes codificações.', '1º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF01CO06', 'ef01co06', 'Reconhecer e explorar artefatos computacionais voltados a atender necessidades pessoais ou coletivas.', '1º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF01CO07', 'ef01co07', 'Conhecer as possibilidades de uso seguro das tecnologias computacionais para proteção dos dados pessoais e para garantir a própria segurança.', '1º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF01ER01', 'ef01er01', 'Identificar e acolher as semelhanças e diferenças entre o eu, o outro e o nós.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01ER02', 'ef01er02', 'Reconhecer que o seu nome e o das demais pessoas os identificam e os diferenciam.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01ER03', 'ef01er03', 'Reconhecer e respeitar as características físicas e subjetivas de cada um.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01ER04', 'ef01er04', 'Valorizar a diversidade de formas de vida.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01ER05', 'ef01er05', 'Identificar e acolher sentimentos, lembranças, memórias e saberes de cada um.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01ER06', 'ef01er06', 'Identificar as diferentes formas pelas quais as pessoas manifestam sentimentos, ideias, memórias, gostos e crenças em diferentes espaços.', '1º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF01GE01', 'ef01ge01', 'Descrever características observadas de seus lugares de vivência (moradia, escola etc.) e identificar semelhanças e diferenças entre esses lugares.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE02', 'ef01ge02', 'Identificar semelhanças e diferenças entre jogos e brincadeiras de diferentes épocas e lugares.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE03', 'ef01ge03', 'Identificar e relatar semelhanças e diferenças de usos do espaço público (praças, parques) para o lazer e diferentes manifestações.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE04', 'ef01ge04', 'Discutir e elaborar, coletivamente, regras de convívio em diferentes espaços (sala de aula, escola etc.).', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE05', 'ef01ge05', 'Observar e descrever ritmos naturais (dia e noite, variação de temperatura e umidade etc.) em diferentes escalas espaciais e temporais, comparando a sua realidade com outras.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE06', 'ef01ge06', 'Descrever e comparar diferentes tipos de moradia ou objetos de uso cotidiano (brinquedos, roupas, mobiliários), considerando técnicas e materiais utilizados em sua produção.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE07', 'ef01ge07', 'Descrever atividades de trabalho relacionadas com o dia a dia da sua comunidade.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE08', 'ef01ge08', 'Criar mapas mentais e desenhos com base em itinerários, contos literários, histórias inventadas e brincadeiras.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE09', 'ef01ge09', 'Elaborar e utilizar mapas simples para localizar elementos do local de vivência, considerando referenciais espaciais (frente e atrás, esquerda e direita, em cima e embaixo, dentro e fora) e tendo o corpo como referência.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE10', 'ef01ge10', 'Descrever características de seus lugares de vivência relacionadas aos ritmos da natureza (chuva, vento, calor etc.).', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01GE11', 'ef01ge11', 'Associar mudanças de vestuário e hábitos alimentares em sua comunidade ao longo do ano, decorrentes da variação de temperatura e umidade no ambiente.', '1º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF01HI01', 'ef01hi01', 'Identificar aspectos do seu crescimento por meio do registro das lembranças particulares ou de lembranças dos membros de sua família e/ou de sua comunidade.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI02', 'ef01hi02', 'Identificar a relação entre as suas histórias e as histórias de sua família e de sua comunidade.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI03', 'ef01hi03', 'Descrever e distinguir os seus papéis e responsabilidades relacionados à família, à escola e à comunidade.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI04', 'ef01hi04', 'Identificar as diferenças entre os variados ambientes em que vive (doméstico, escolar e da comunidade), reconhecendo as especificidades dos hábitos e das regras que os regem.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI05', 'ef01hi05', 'Identificar semelhanças e diferenças entre jogos e brincadeiras atuais e de outras épocas e lugares.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI06', 'ef01hi06', 'Conhecer as histórias da família e da escola e identificar o papel desempenhado por diferentes sujeitos em diferentes espaços.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI07', 'ef01hi07', 'Identificar mudanças e permanências nas formas de organização familiar.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01HI08', 'ef01hi08', 'Reconhecer o significado das comemorações e festas escolares, diferenciando-as das datas festivas comemoradas no âmbito familiar ou da comunidade.', '1º ano(s) do Ensino Fundamental', 'História'),
  ('EF01LP01', 'ef01lp01', 'Reconhecer que textos são lidos e escritos da esquerda para a direita e de cima para baixo da página.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP02', 'ef01lp02', 'Escrever, espontaneamente ou por ditado, palavras e frases de forma alfabética – usando letras/grafemas que representem fonemas.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP03', 'ef01lp03', 'Observar escritas convencionais, comparando-as às suas produções escritas, percebendo semelhanças e diferenças.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP04', 'ef01lp04', 'Distinguir as letras do alfabeto de outros sinais gráficos.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP05', 'ef01lp05', 'Reconhecer o sistema de escrita alfabética como representação dos sons da fala.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP06', 'ef01lp06', 'Segmentar oralmente palavras em sílabas.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP07', 'ef01lp07', 'Identificar fonemas e sua representação por letras.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP08', 'ef01lp08', 'Relacionar elementos sonoros (sílabas, fonemas, partes de palavras) com sua representação escrita.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP09', 'ef01lp09', 'Comparar palavras, identificando semelhanças e diferenças entre sons de sílabas iniciais.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP10', 'ef01lp10', 'Nomear as letras do alfabeto e recitá-lo na ordem das letras.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP11', 'ef01lp11', 'Conhecer, diferenciar e relacionar letras em formato imprensa e cursiva, maiúsculas e minúsculas.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP12', 'ef01lp12', 'Reconhecer a separação das palavras, na escrita, por espaços em branco.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP13', 'ef01lp13', 'Comparar palavras, identificando semelhanças e diferenças entre sons de sílabas mediais e finais.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP14', 'ef01lp14', 'Identificar outros sinais no texto além das letras, como pontos finais, de interrogação e exclamação e seus efeitos na entonação.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP15', 'ef01lp15', 'Agrupar palavras pelo critério de aproximação de significado (sinonímia) e separar palavras pelo critério de oposição de significado (antonímia).', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP16', 'ef01lp16', 'Ler e compreender, em colaboração com os colegas e com a ajuda do professor, quadras, quadrinhas, parlendas, trava-línguas, dentre outros gêneros do campo da vida cotidiana, considerando a situação comunicativa e o tema/assunto do texto e relacionando sua forma de organização à sua finalidade.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP17', 'ef01lp17', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, listas, agendas, calendários, avisos, convites, receitas, instruções de montagem e legendas para álbuns, fotos ou ilustrações (digitais ou impressos), dentre outros gêneros do campo da vida cotidiana, considerando a situação comunicativa e o tema/assunto/ finalidade do texto.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP18', 'ef01lp18', 'Registrar, em colaboração com os colegas e com a ajuda do professor, cantigas, quadras, quadrinhas, parlendas, trava-línguas, dentre outros gêneros do campo da vida cotidiana, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP19', 'ef01lp19', 'Recitar parlendas, quadras, quadrinhas, trava-línguas, com entonação adequada e observando as rimas.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP20', 'ef01lp20', 'Identificar e reproduzir, em listas, agendas, calendários, regras, avisos, convites, receitas, instruções de montagem e legendas para álbuns, fotos ou ilustrações (digitais ou impressos), a formatação e diagramação específica de cada um desses gêneros.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP21', 'ef01lp21', 'Escrever, em colaboração com os colegas e com a ajuda do professor, listas de regras e regulamentos que organizam a vida na comunidade escolar, dentre outros gêneros do campo da atuação cidadã, considerando a situação comunicativa e o tema/assunto do texto.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP22', 'ef01lp22', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, diagramas, entrevistas, curiosidades, dentre outros gêneros do campo investigativo, digitais ou impressos, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP23', 'ef01lp23', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, entrevistas, curiosidades, dentre outros gêneros do campo investigativo, que possam ser repassados oralmente por meio de ferramentas digitais, em áudio ou vídeo, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP24', 'ef01lp24', 'Identificar e reproduzir, em enunciados de tarefas escolares, diagramas, entrevistas, curiosidades, digitais ou impressos, a formatação e diagramação específica de cada um desses gêneros, inclusive em suas versões orais.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP25', 'ef01lp25', 'Produzir, tendo o professor como escriba, recontagens de histórias lidas pelo professor, histórias imaginadas ou baseadas em livros de imagens, observando a forma de composição de textos narrativos (personagens, enredo, tempo e espaço).', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01LP26', 'ef01lp26', 'Identificar elementos de uma narrativa lida ou escutada, incluindo personagens, enredo, tempo e espaço.', '1º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF01MA01', 'ef01ma01', 'Utilizar números naturais como indicador de quantidade ou de ordem em diferentes situações cotidianas e reconhecer situações em que os números não indicam contagem nem ordem, mas sim código de identificação.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA02', 'ef01ma02', 'Contar de maneira exata ou aproximada, utilizando diferentes estratégias como o pareamento e outros agrupamentos.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA03', 'ef01ma03', 'Estimar e comparar quantidades de objetos de dois conjuntos (em torno de 20 elementos), por estimativa e/ou por correspondência (um a um, dois a dois) para indicar “tem mais”, “tem menos” ou “tem a mesma quantidade”.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA04', 'ef01ma04', 'Contar a quantidade de objetos de coleções até 100 unidades e apresentar o resultado por registros verbais e simbólicos, em situações de seu interesse, como jogos, brincadeiras, materiais da sala de aula, entre outros.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA05', 'ef01ma05', 'Comparar números naturais de até duas ordens em situações cotidianas, com e sem suporte da reta numérica.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA06', 'ef01ma06', 'Construir fatos básicos da adição e utilizá-los em procedimentos de cálculo para resolver problemas.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA07', 'ef01ma07', 'Compor e decompor número de até duas ordens, por meio de diferentes adições, com o suporte de material manipulável, contribuindo para a compreensão de características do sistema de numeração decimal e o desenvolvimento de estratégias de cálculo.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA08', 'ef01ma08', 'Resolver e elaborar problemas de adição e de subtração, envolvendo números de até dois algarismos, com os significados de juntar, acrescentar, separar e retirar, com o suporte de imagens e/ou material manipulável, utilizando estratégias e formas de registro pessoais.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA09', 'ef01ma09', 'Organizar e ordenar objetos familiares ou representações por figuras, por meio de atributos, tais como cor, forma e medida.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA10', 'ef01ma10', 'Descrever, após o reconhecimento e a explicitação de um padrão (ou regularidade), os elementos ausentes em sequências recursivas de números naturais, objetos ou figuras.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA11', 'ef01ma11', 'Descrever a localização de pessoas e de objetos no espaço em relação à sua própria posição, utilizando termos como à direita, à esquerda, em frente, atrás.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA12', 'ef01ma12', 'Descrever a localização de pessoas e de objetos no espaço segundo um dado ponto de referência, compreendendo que, para a utilização de termos que se referem à posição, como direita, esquerda, em cima, em baixo, é necessário explicitar-se o referencial.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA13', 'ef01ma13', 'Relacionar figuras geométricas espaciais (cones, cilindros, esferas e blocos retangulares) a objetos familiares do mundo físico.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA14', 'ef01ma14', 'Identificar e nomear figuras planas (círculo, quadrado, retângulo e triângulo) em desenhos apresentados em diferentes disposições ou em contornos de faces de sólidos geométricos.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA15', 'ef01ma15', 'Comparar comprimentos, capacidades ou massas, utilizando termos como mais alto, mais baixo, mais comprido, mais curto, mais grosso, mais fino, mais largo, mais pesado, mais leve, cabe mais, cabe menos, entre outros, para ordenar objetos de uso cotidiano.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA16', 'ef01ma16', 'Relatar em linguagem verbal ou não verbal sequência de acontecimentos relativos a um dia, utilizando, quando possível, os horários dos eventos.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA17', 'ef01ma17', 'Reconhecer e relacionar períodos do dia, dias da semana e meses do ano, utilizando calendário, quando necessário.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA18', 'ef01ma18', 'Produzir a escrita de uma data, apresentando o dia, o mês e o ano, e indicar o dia da semana de uma data, consultando calendários.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA19', 'ef01ma19', 'Reconhecer e relacionar valores de moedas e cédulas do sistema monetário brasileiro para resolver situações simples do cotidiano do estudante.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA20', 'ef01ma20', 'Classificar eventos envolvendo o acaso, tais como “acontecerá com certeza”, “talvez aconteça” e “é impossível acontecer”, em situações do cotidiano.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA21', 'ef01ma21', 'Ler dados expressos em tabelas e em gráficos de colunas simples.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF01MA22', 'ef01ma22', 'Realizar pesquisa, envolvendo até duas variáveis categóricas de seu interesse e universo de até 30 elementos, e organizar dados por meio de representações pessoais.', '1º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02CI01', 'ef02ci01', 'Identificar de que materiais (metais, madeira, vidro etc.) são feitos os objetos que fazem parte da vida cotidiana, como esses objetos são utilizados e com quais materiais eram produzidos no passado.', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI02', 'ef02ci02', 'Propor o uso de diferentes materiais para a construção de objetos de uso cotidiano, tendo em vista algumas propriedades desses materiais (flexibilidade, dureza, transparência etc.).', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI03', 'ef02ci03', 'Discutir os cuidados necessários à prevenção de acidentes domésticos (objetos cortantes e inflamáveis, eletricidade, produtos de limpeza, medicamentos etc.).', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI04', 'ef02ci04', 'Descrever características de plantas e animais (tamanho, forma, cor, fase da vida, local onde se desenvolvem etc.) que fazem parte de seu cotidiano e relacioná-las ao ambiente em que eles vivem.', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI05', 'ef02ci05', 'Investigar a importância da água e da luz para a manutenção da vida de plantas em geral.', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI06', 'ef02ci06', 'Identificar as principais partes de uma planta (raiz, caule, folhas, flores e frutos) e a função desempenhada por cada uma delas, e analisar as relações entre as plantas, o ambiente e os demais seres vivos.', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI07', 'ef02ci07', 'Descrever as posições do Sol em diversos horários do dia e associá-las ao tamanho da sombra projetada.', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CI08', 'ef02ci08', 'Comparar o efeito da radiação solar (aquecimento e reflexão) em diferentes tipos de superfície (água, areia, solo, superfícies escura, clara e metálica etc.).', '2º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF02CO01', 'ef02co01', 'Criar e comparar modelos (representações) de objetos, identificando padrões e atributos essenciais.', '2º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF02CO02', 'ef02co02', 'Criar e simular algoritmos representados em linguagem oral, escrita ou pictográfica, construídos como sequências com repetições simples (iterações definidas) com base em instruções preestabelecidas ou criadas, analisando como a precisão da instrução impacta na execução do algoritmo.', '2º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF02CO03', 'ef02co03', 'Identificar que máquinas diferentes executam conjuntos próprios de instruções e que podem ser usadas para definir algoritmos.', '2º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF02CO04', 'ef02co04', 'Diferenciar componentes físicos (hardware) e programas que fornecem as instruções (software) para o hardware.', '2º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF02CO05', 'ef02co05', 'Reconhecer as características e usos das tecnologias computacionais no cotidiano dentro e fora da escola.', '2º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF02CO06', 'ef02co06', 'Reconhecer os cuidados com a segurança no uso de dispositivos computacionais.', '2º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF02ER01', 'ef02er01', 'Reconhecer os diferentes espaços de convivência.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER02', 'ef02er02', 'Identificar costumes, crenças e formas diversas de viver em variados ambientes de convivência.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER03', 'ef02er03', 'Identificar as diferentes formas de registro das memórias pessoais, familiares e escolares (fotos, músicas, narrativas, álbuns...).', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER04', 'ef02er04', 'Identificar os símbolos presentes nos variados espaços de convivência.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER05', 'ef02er05', 'Identificar, distinguir e respeitar símbolos religiosos de distintas manifestações, tradições e instituições religiosas.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER06', 'ef02er06', 'Exemplificar alimentos considerados sagrados por diferentes culturas, tradições e expressões religiosas.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02ER07', 'ef02er07', 'Identificar significados atribuídos a alimentos em diferentes manifestações e tradições religiosas.', '2º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF02GE01', 'ef02ge01', 'Descrever a história das migrações no bairro ou comunidade em que vive.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE02', 'ef02ge02', 'Comparar costumes e tradições de diferentes populações inseridas no bairro ou comunidade em que vive, reconhecendo a importância do respeito às diferenças.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE03', 'ef02ge03', 'Comparar diferentes meios de transporte e de comunicação, indicando o seu papel na conexão entre lugares, e discutir os riscos para a vida e para o ambiente e seu uso responsável.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE04', 'ef02ge04', 'Reconhecer semelhanças e diferenças nos hábitos, nas relações com a natureza e no modo de viver de pessoas em diferentes lugares.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE05', 'ef02ge05', 'Analisar mudanças e permanências, comparando imagens de um mesmo lugar em diferentes tempos.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE06', 'ef02ge06', 'Relacionar o dia e a noite a diferentes tipos de atividades sociais (horário escolar, comercial, sono etc.).', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE07', 'ef02ge07', 'Descrever as atividades extrativas (minerais, agropecuárias e industriais) de diferentes lugares, identificando os impactos ambientais.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE08', 'ef02ge08', 'Identificar e elaborar diferentes formas de representação (desenhos, mapas mentais, maquetes) para representar componentes da paisagem dos lugares de vivência.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE09', 'ef02ge09', 'Identificar objetos e lugares de vivência (escola e moradia) em imagens aéreas e mapas (visão vertical) e fotografias (visão oblíqua).', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE10', 'ef02ge10', 'Aplicar princípios de localização e posição de objetos (referenciais espaciais, como frente e atrás, esquerda e direita, em cima e embaixo, dentro e fora) por meio de representações espaciais da sala de aula e da escola.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02GE11', 'ef02ge11', 'Reconhecer a importância do solo e da água para a vida, identificando seus diferentes usos (plantação e extração de materiais, entre outras possibilidades) e os impactos desses usos no cotidiano da cidade e do campo.', '2º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF02HI01', 'ef02hi01', 'Reconhecer espaços de sociabilidade e identificar os motivos que aproximam e separam as pessoas em diferentes grupos sociais ou de parentesco.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI02', 'ef02hi02', 'Identificar e descrever práticas e papéis sociais que as pessoas exercem em diferentes comunidades.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI03', 'ef02hi03', 'Selecionar situações cotidianas que remetam à percepção de mudança, pertencimento e memória.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI04', 'ef02hi04', 'Selecionar e compreender o significado de objetos e documentos pessoais como fontes de memórias e histórias nos âmbitos pessoal, familiar, escolar e comunitário.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI05', 'ef02hi05', 'Selecionar objetos e documentos pessoais e de grupos próximos ao seu convívio e compreender sua função, seu uso e seu significado.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI06', 'ef02hi06', 'Identificar e organizar, temporalmente, fatos da vida cotidiana, usando noções relacionadas ao tempo (antes, durante, ao mesmo tempo e depois).', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI07', 'ef02hi07', 'Identificar e utilizar diferentes marcadores do tempo presentes na comunidade, como relógio e calendário.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI08', 'ef02hi08', 'Compilar histórias da família e/ou da comunidade registradas em diferentes fontes.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI09', 'ef02hi09', 'Identificar objetos e documentos pessoais que remetam à própria experiência no âmbito da família e/ou da comunidade, discutindo as razões pelas quais alguns objetos são preservados e outros são descartados.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI10', 'ef02hi10', 'Identificar diferentes formas de trabalho existentes na comunidade em que vive, seus significados, suas especificidades e importância.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02HI11', 'ef02hi11', 'Identificar impactos no ambiente causados pelas diferentes formas de trabalho existentes na comunidade em que vive.', '2º ano(s) do Ensino Fundamental', 'História'),
  ('EF02LP01', 'ef02lp01', 'Utilizar, ao produzir o texto, grafia correta de palavras conhecidas ou com estruturas silábicas já dominadas, letras maiúsculas em início de frases e em substantivos próprios, segmentação entre as palavras, ponto final, ponto de interrogação e ponto de exclamação.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP02', 'ef02lp02', 'Segmentar palavras em sílabas e remover e substituir sílabas iniciais, mediais ou finais para criar novas palavras.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP03', 'ef02lp03', 'Ler e escrever palavras com correspondências regulares diretas entre letras e fonemas (f, v, t, d, p, b) e correspondências regulares contextuais (c e q; e e o, em posição átona em final de palavra).', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP04', 'ef02lp04', 'Ler e escrever corretamente palavras com sílabas CV, V, CVC, CCV, identificando que existem vogais em todas as sílabas.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP05', 'ef02lp05', 'Ler e escrever corretamente palavras com marcas de nasalidade (til, m, n).', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP06', 'ef02lp06', 'Perceber o princípio acrofônico que opera nos nomes das letras do alfabeto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP07', 'ef02lp07', 'Escrever palavras, frases, textos curtos nas formas imprensa e cursiva.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP08', 'ef02lp08', 'Segmentar corretamente as palavras ao escrever frases e textos.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP09', 'ef02lp09', 'Usar adequadamente ponto final, ponto de interrogação e ponto de exclamação.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP10', 'ef02lp10', 'Identificar sinônimos de palavras de texto lido, determinando a diferença de sentido entre eles, e formar antônimos de palavras encontradas em texto lido pelo acréscimo do prefixo de negação in-/im-.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP11', 'ef02lp11', 'Formar o aumentativo e o diminutivo de palavras com os sufixos -ão e -inho/-zinho.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP12', 'ef02lp12', 'Ler e compreender com certa autonomia cantigas, letras de canção, dentre outros gêneros do campo da vida cotidiana, considerando a situação comunicativa e o tema/assunto do texto e relacionando sua forma de organização à sua finalidade.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP13', 'ef02lp13', 'Planejar e produzir bilhetes e cartas, em meio impresso e/ou digital, dentre outros gêneros do campo da vida cotidiana, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP14', 'ef02lp14', 'Planejar e produzir pequenos relatos de observação de processos, de fatos, de experiências pessoais, mantendo as características do gênero, considerando a situação comunicativa e o tema/assunto do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP15', 'ef02lp15', 'Cantar cantigas e canções, obedecendo ao ritmo e à melodia.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP16', 'ef02lp16', 'Identificar e reproduzir, em bilhetes, recados, avisos, cartas, e-mails, receitas (modo de fazer), relatos (digitais ou impressos), a formatação e diagramação específica de cada um desses gêneros.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP17', 'ef02lp17', 'Identificar e reproduzir, em relatos de experiências pessoais, a sequência dos fatos, utilizando expressões que marquem a passagem do tempo (“antes”, “depois”, “ontem”, “hoje”, “amanhã”, “outro dia”, “antigamente”, “há muito tempo” etc.), e o nível de informatividade necessário.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP18', 'ef02lp18', 'Planejar e produzir cartazes e folhetos para divulgar eventos da escola ou da comunidade, utilizando linguagem persuasiva e elementos textuais e visuais (tamanho da letra, leiaute, imagens) adequados ao gênero, considerando a situação comunicativa e o tema/assunto do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP19', 'ef02lp19', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, notícias curtas para público infantil, para compor jornal falado que possa ser repassado oralmente ou em meio digital, em áudio ou vídeo, dentre outros gêneros do campo jornalístico, considerando a situação comunicativa e o tema/assunto do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP20', 'ef02lp20', 'Reconhecer a função de textos utilizados para apresentar informações coletadas em atividades de pesquisa (enquetes, pequenas entrevistas, registros de experimentações).', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP21', 'ef02lp21', 'Explorar, com a mediação do professor, textos informativos de diferentes ambientes digitais de pesquisa, conhecendo suas possibilidades.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP22', 'ef02lp22', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, pequenos relatos de experimentos, entrevistas, verbetes de enciclopédia infantil, dentre outros gêneros do campo investigativo, digitais ou impressos, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP23', 'ef02lp23', 'Planejar e produzir, com certa autonomia, pequenos registros de observação de resultados de pesquisa, coerentes com um tema investigado.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP24', 'ef02lp24', 'Planejar e produzir, em colaboração com os colegas e com a ajuda do professor, relatos de experimentos, registros de observação, entrevistas, dentre outros gêneros do campo investigativo, que possam ser repassados oralmente por meio de ferramentas digitais, em áudio ou vídeo, considerando a situação comunicativa e o tema/assunto/ finalidade do texto.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP25', 'ef02lp25', 'Identificar e reproduzir, em relatos de experimentos, entrevistas, verbetes de enciclopédia infantil, digitais ou impressos, a formatação e diagramação específica de cada um desses gêneros, inclusive em suas versões orais.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP26', 'ef02lp26', 'Ler e compreender, com certa autonomia, textos literários, de gêneros variados, desenvolvendo o gosto pela leitura.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP27', 'ef02lp27', 'Reescrever textos narrativos literários lidos pelo professor.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP28', 'ef02lp28', 'Reconhecer o conflito gerador de uma narrativa ficcional e sua resolução, além de palavras, expressões e frases que caracterizam personagens e ambientes.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02LP29', 'ef02lp29', 'Observar, em poemas visuais, o formato do texto na página, as ilustrações e outros efeitos visuais.', '2º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF02MA01', 'ef02ma01', 'Comparar e ordenar números naturais (até a ordem de centenas) pela compreensão de características do sistema de numeração decimal (valor posicional e função do zero).', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA02', 'ef02ma02', 'Fazer estimativas por meio de estratégias diversas a respeito da quantidade de objetos de coleções e registrar o resultado da contagem desses objetos (até 1000 unidades).', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA03', 'ef02ma03', 'Comparar quantidades de objetos de dois conjuntos, por estimativa e/ou por correspondência (um a um, dois a dois, entre outros), para indicar “tem mais”, “tem menos” ou “tem a mesma quantidade”, indicando, quando for o caso, quantos a mais e quantos a menos.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA04', 'ef02ma04', 'Compor e decompor números naturais de até três ordens, com suporte de material manipulável, por meio de diferentes adições.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA05', 'ef02ma05', 'Construir fatos básicos da adição e subtração e utilizá-los no cálculo mental ou escrito.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA06', 'ef02ma06', 'Resolver e elaborar problemas de adição e de subtração, envolvendo números de até três ordens, com os significados de juntar, acrescentar, separar, retirar, utilizando estratégias pessoais.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA07', 'ef02ma07', 'Resolver e elaborar problemas de multiplicação (por 2, 3, 4 e 5) com a ideia de adição de parcelas iguais por meio de estratégias e formas de registro pessoais, utilizando ou não suporte de imagens e/ou material manipulável.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA08', 'ef02ma08', 'Resolver e elaborar problemas envolvendo dobro, metade, triplo e terça parte, com o suporte de imagens ou material manipulável, utilizando estratégias pessoais.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA09', 'ef02ma09', 'Construir sequências de números naturais em ordem crescente ou decrescente a partir de um número qualquer, utilizando uma regularidade estabelecida.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA10', 'ef02ma10', 'Descrever um padrão (ou regularidade) de sequências repetitivas e de sequências recursivas, por meio de palavras, símbolos ou desenhos.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA11', 'ef02ma11', 'Descrever os elementos ausentes em sequências repetitivas e em sequências recursivas de números naturais, objetos ou figuras.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA12', 'ef02ma12', 'Identificar e registrar, em linguagem verbal ou não verbal, a localização e os deslocamentos de pessoas e de objetos no espaço, considerando mais de um ponto de referência, e indicar as mudanças de direção e de sentido.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA13', 'ef02ma13', 'Esboçar roteiros a ser seguidos ou plantas de ambientes familiares, assinalando entradas, saídas e alguns pontos de referência.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA14', 'ef02ma14', 'Reconhecer, nomear e comparar figuras geométricas espaciais (cubo, bloco retangular, pirâmide, cone, cilindro e esfera), relacionando-as com objetos do mundo físico.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA15', 'ef02ma15', 'Reconhecer, comparar e nomear figuras planas (círculo, quadrado, retângulo e triângulo), por meio de características comuns, em desenhos apresentados em diferentes disposições ou em sólidos geométricos.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA16', 'ef02ma16', 'Estimar, medir e comparar comprimentos de lados de salas (incluindo contorno) e de polígonos, utilizando unidades de medida não padronizadas e padronizadas (metro, centímetro e milímetro) e instrumentos adequados.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA17', 'ef02ma17', 'Estimar, medir e comparar capacidade e massa, utilizando estratégias pessoais e unidades de medida não padronizadas ou padronizadas (litro, mililitro, grama e quilograma).', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA18', 'ef02ma18', 'Indicar a duração de intervalos de tempo entre duas datas, como dias da semana e meses do ano, utilizando calendário, para planejamentos e organização de agenda.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA19', 'ef02ma19', 'Medir a duração de um intervalo de tempo por meio de relógio digital e registrar o horário do início e do fim do intervalo.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA20', 'ef02ma20', 'Estabelecer a equivalência de valores entre moedas e cédulas do sistema monetário brasileiro para resolver situações cotidianas.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA21', 'ef02ma21', 'Classificar resultados de eventos cotidianos aleatórios como “pouco prováveis”, “muito prováveis”, “improváveis” e “impossíveis”.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA22', 'ef02ma22', 'Comparar informações de pesquisas apresentadas por meio de tabelas de dupla entrada e em gráficos de colunas simples ou barras, para melhor compreender aspectos da realidade próxima.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF02MA23', 'ef02ma23', 'Realizar pesquisa em universo de até 30 elementos, escolhendo até três variáveis categóricas de seu interesse, organizando os dados coletados em listas, tabelas e gráficos de colunas simples.', '2º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03CI01', 'ef03ci01', 'Produzir diferentes sons a partir da vibração de variados objetos e identificar variáveis que influem nesse fenômeno.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI02', 'ef03ci02', 'Experimentar e relatar o que ocorre com a passagem da luz através de objetos transparentes (copos, janelas de vidro, lentes, prismas, água etc.), no contato com superfícies polidas (espelhos) e na intersecção com objetos opacos (paredes, pratos, pessoas e outros objetos de uso cotidiano).', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI03', 'ef03ci03', 'Discutir hábitos necessários para a manutenção da saúde auditiva e visual considerando as condições do ambiente em termos de som e luz.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI04', 'ef03ci04', 'Identificar características sobre o modo de vida (o que comem, como se reproduzem, como se deslocam etc.) dos animais mais comuns no ambiente próximo.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI05', 'ef03ci05', 'Descrever e comunicar as alterações que ocorrem desde o nascimento em animais de diferentes meios terrestres ou aquáticos, inclusive o homem.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI06', 'ef03ci06', 'Comparar alguns animais e organizar grupos com base em características externas comuns (presença de penas, pelos, escamas, bico, garras, antenas, patas etc.).', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI07', 'ef03ci07', 'Identificar características da Terra (como seu formato esférico, a presença de água, solo etc.), com base na observação, manipulação e comparação de diferentes formas de representação do planeta (mapas, globos, fotografias etc.).', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI08', 'ef03ci08', 'Observar, identificar e registrar os períodos diários (dia e/ou noite) em que o Sol, demais estrelas, Lua e planetas estão visíveis no céu.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI09', 'ef03ci09', 'Comparar diferentes amostras de solo do entorno da escola com base em características como cor, textura, cheiro, tamanho das partículas, permeabilidade etc.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CI10', 'ef03ci10', 'Identificar os diferentes usos do solo (plantação e extração de materiais, dentre outras possibilidades), reconhecendo a importância do solo para a agricultura e para a vida.', '3º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF03CO01', 'ef03co01', 'Associar os valores ''verdadeiro'' e ''falso'' a sentenças lógicas que dizem respeito a situações do dia a dia, fazendo uso de termos que indicam negação.', '3º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF03CO02', 'ef03co02', 'Criar e simular algoritmos representados em linguagem oral, escrita ou pictográfica, que incluam sequências e repetições simples com condição (iterações indefinidas), para resolver problemas de forma independente e em colaboração.', '3º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF03CO03', 'ef03co03', 'Aplicar a estratégia de decomposição para resolver problemas complexos, dividindo esse problema em partes menores, resolvendo-as e combinando suas soluções.', '3º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF03CO04', 'ef03co04', 'Relacionar o conceito de informação com o de dado.', '3º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF03CO05', 'ef03co05', 'Compreender que dados são estruturados em formatos específicos dependendo da informação armazenada.', '3º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF03CO06', 'ef03co06', 'Reconhecer que, para um computador realizar tarefas, ele se comunica com o mundo exterior com o uso de interfaces físicas (dispositivos de entrada e saída).', '3º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF03CO07', 'ef03co07', 'Utilizar diferentes navegadores e ferramentas de busca para pesquisar e acessar informações.', '3º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF03CO08', 'ef03co08', 'Usar ferramentas computacionais em situações didáticas para se expressar em diferentes formatos digitais.', '3º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF03CO09', 'ef03co09', 'Reconhecer o potencial impacto do compartilhamento de informações pessoais ou de seus pares em meio digital.', '3º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF03ER01', 'ef03er01', 'Identificar e respeitar os diferentes espaços e territórios religiosos de diferentes tradições e movimentos religiosos.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03ER02', 'ef03er02', 'Caracterizar os espaços e territórios religiosos como locais de realização das práticas celebrativas.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03ER03', 'ef03er03', 'Identificar e respeitar práticas celebrativas (cerimônias, orações, festividades, peregrinações, entre outras) de diferentes tradições religiosas.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03ER04', 'ef03er04', 'Caracterizar as práticas celebrativas como parte integrante do conjunto das manifestações religiosas de diferentes culturas e sociedades.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03ER05', 'ef03er05', 'Reconhecer as indumentárias (roupas, acessórios, símbolos, pinturas corporais) utilizadas em diferentes manifestações e tradições religiosas.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03ER06', 'ef03er06', 'Caracterizar as indumentárias como elementos integrantes das identidades religiosas.', '3º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF03GE01', 'ef03ge01', 'Identificar e comparar aspectos culturais dos grupos sociais de seus lugares de vivência, seja na cidade, seja no campo.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE02', 'ef03ge02', 'Identificar, em seus lugares de vivência, marcas de contribuição cultural e econômica de grupos de diferentes origens.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE03', 'ef03ge03', 'Reconhecer os diferentes modos de vida de povos e comunidades tradicionais em distintos lugares.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE04', 'ef03ge04', 'Explicar como os processos naturais e históricos atuam na produção e na mudança das paisagens naturais e antrópicas nos seus lugares de vivência, comparando-os a outros lugares.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE05', 'ef03ge05', 'Identificar alimentos, minerais e outros produtos cultivados e extraídos da natureza, comparando as atividades de trabalho em diferentes lugares.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE06', 'ef03ge06', 'Identificar e interpretar imagens bidimensionais e tridimensionais em diferentes tipos de representação cartográfica.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE07', 'ef03ge07', 'Reconhecer e elaborar legendas com símbolos de diversos tipos de representações em diferentes escalas cartográficas.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE08', 'ef03ge08', 'Relacionar a produção de lixo doméstico ou da escola aos problemas causados pelo consumo excessivo e construir propostas para o consumo consciente, considerando a ampliação de hábitos de redução, reúso e reciclagem/ descarte de materiais consumidos em casa, na escola e/ou no entorno.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE09', 'ef03ge09', 'Investigar os usos dos recursos naturais, com destaque para os usos da água em atividades cotidianas (alimentação, higiene, cultivo de plantas etc.), e discutir os problemas ambientais provocados por esses usos.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE10', 'ef03ge10', 'Identificar os cuidados necessários para utilização da água na agricultura e na geração de energia de modo a garantir a manutenção do provimento de água potável.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03GE11', 'ef03ge11', 'Comparar impactos das atividades econômicas urbanas e rurais sobre o ambiente físico natural, assim como os riscos provenientes do uso de ferramentas e máquinas.', '3º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF03HI01', 'ef03hi01', 'Identificar os grupos populacionais que formam a cidade, o município e a região, as relações estabelecidas entre eles e os eventos que marcam a formação da cidade, como fenômenos migratórios (vida rural/vida urbana), desmatamentos, estabelecimento de grandes empresas etc.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI02', 'ef03hi02', 'Selecionar, por meio da consulta de fontes de diferentes naturezas, e registrar acontecimentos ocorridos ao longo do tempo na cidade ou região em que vive.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI03', 'ef03hi03', 'Identificar e comparar pontos de vista em relação a eventos significativos do local em que vive, aspectos relacionados a condições sociais e à presença de diferentes grupos sociais e culturais, com especial destaque para as culturas africanas, indígenas e de migrantes.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI04', 'ef03hi04', 'Identificar os patrimônios históricos e culturais de sua cidade ou região e discutir as razões culturais, sociais e políticas para que assim sejam considerados.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI05', 'ef03hi05', 'Identificar os marcos históricos do lugar em que vive e compreender seus significados.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI06', 'ef03hi06', 'Identificar os registros de memória na cidade (nomes de ruas, monumentos, edifícios etc.), discutindo os critérios que explicam a escolha desses nomes.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI07', 'ef03hi07', 'Identificar semelhanças e diferenças existentes entre comunidades de sua cidade ou região, e descrever o papel dos diferentes grupos sociais que as formam.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI08', 'ef03hi08', 'Identificar modos de vida na cidade e no campo no presente, comparando-os com os do passado.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI09', 'ef03hi09', 'Mapear os espaços públicos no lugar em que vive (ruas, praças, escolas, hospitais, prédios da Prefeitura e da Câmara de Vereadores etc.) e identificar suas funções.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI10', 'ef03hi10', 'Identificar as diferenças entre o espaço doméstico, os espaços públicos e as áreas de conservação ambiental, compreendendo a importância dessa distinção.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI11', 'ef03hi11', 'Identificar diferenças entre formas de trabalho realizadas na cidade e no campo, considerando também o uso da tecnologia nesses diferentes contextos.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03HI12', 'ef03hi12', 'Comparar as relações de trabalho e lazer do presente com as de outros tempos e espaços, analisando mudanças e permanências.', '3º ano(s) do Ensino Fundamental', 'História'),
  ('EF03LP01', 'ef03lp01', 'Ler e escrever palavras com correspondências regulares contextuais entre grafemas e fonemas – c/qu; g/gu; r/rr; s/ss; o (e não u) e e (e não i) em sílaba átona em final de palavra – e com marcas de nasalidade (til, m, n).', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP02', 'ef03lp02', 'Ler e escrever corretamente palavras com sílabas CV, V, CVC, CCV, VC, VV, CVV, identificando que existem vogais em todas as sílabas.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP03', 'ef03lp03', 'Ler e escrever corretamente palavras com os dígrafos lh, nh, ch.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP04', 'ef03lp04', 'Usar acento gráfico (agudo ou circunflexo) em monossílabos tônicos terminados em a, e, o e em palavras oxítonas terminadas em a, e, o, seguidas ou não de s.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP05', 'ef03lp05', 'Identificar o número de sílabas de palavras, classificando-as em monossílabas, dissílabas, trissílabas e polissílabas.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP06', 'ef03lp06', 'Identificar a sílaba tônica em palavras, classificando-as em oxítonas, paroxítonas e proparoxítonas.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP07', 'ef03lp07', 'Identificar a função na leitura e usar na escrita ponto final, ponto de interrogação, ponto de exclamação e, em diálogos (discurso direto), dois-pontos e travessão.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP08', 'ef03lp08', 'Identificar e diferenciar, em textos, substantivos e verbos e suas funções na oração: agente, ação, objeto da ação.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP09', 'ef03lp09', 'Identificar, em textos, adjetivos e sua função de atribuição de propriedades aos substantivos.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP10', 'ef03lp10', 'Reconhecer prefixos e sufixos produtivos na formação de palavras derivadas de substantivos, de adjetivos e de verbos, utilizando-os para compreender palavras e para formar novas palavras.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP11', 'ef03lp11', 'Ler e compreender, com autonomia, textos injuntivos instrucionais (receitas, instruções de montagem etc.), com a estrutura própria desses textos (verbos imperativos, indicação de passos a ser seguidos) e mesclando palavras, imagens e recursos gráfico-visuais, considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP12', 'ef03lp12', 'Ler e compreender, com autonomia, cartas pessoais e diários, com expressão de sentimentos e opiniões, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero carta e considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP13', 'ef03lp13', 'Planejar e produzir cartas pessoais e diários, com expressão de sentimentos e opiniões, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções dos gêneros carta e diário e considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP14', 'ef03lp14', 'Planejar e produzir textos injuntivos instrucionais, com a estrutura própria desses textos (verbos imperativos, indicação de passos a ser seguidos) e mesclando palavras, imagens e recursos gráfico-visuais, considerando a situação comunicativa e o tema/ assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP15', 'ef03lp15', 'Assistir, em vídeo digital, a programa de culinária infantil e, a partir dele, planejar e produzir receitas em áudio ou vídeo.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP16', 'ef03lp16', 'Identificar e reproduzir, em textos injuntivos instrucionais (receitas, instruções de montagem, digitais ou impressos), a formatação própria desses textos (verbos imperativos, indicação de passos a ser seguidos) e a diagramação específica dos textos desses gêneros (lista de ingredientes ou materiais e instruções de execução – "modo de fazer").', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP17', 'ef03lp17', 'Identificar e reproduzir, em gêneros epistolares e diários, a formatação própria desses textos (relatos de acontecimentos, expressão de vivências, emoções, opiniões ou críticas) e a diagramação específica dos textos desses gêneros (data, saudação, corpo do texto, despedida, assinatura).', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP18', 'ef03lp18', 'Ler e compreender, com autonomia, cartas dirigidas a veículos da mídia impressa ou digital (cartas de leitor e de reclamação a jornais, revistas) e notícias, dentre outros gêneros do campo jornalístico, de acordo com as convenções do gênero carta e considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP19', 'ef03lp19', 'Identificar e discutir o propósito do uso de recursos de persuasão (cores, imagens, escolha de palavras, jogo de palavras, tamanho de letras) em textos publicitários e de propaganda, como elementos de convencimento.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP20', 'ef03lp20', 'Produzir cartas dirigidas a veículos da mídia impressa ou digital (cartas do leitor ou de reclamação a jornais ou revistas), dentre outros gêneros do campo político-cidadão, com opiniões e críticas, de acordo com as convenções do gênero carta e considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP21', 'ef03lp21', 'Produzir anúncios publicitários, textos de campanhas de conscientização destinados ao público infantil, observando os recursos de persuasão utilizados nos textos publicitários e de propaganda (cores, imagens, slogan, escolha de palavras, jogo de palavras, tamanho e tipo de letras, diagramação).', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP22', 'ef03lp22', 'Planejar e produzir, em colaboração com os colegas, telejornal para público infantil com algumas notícias e textos de campanhas que possam ser repassados oralmente ou em meio digital, em áudio ou vídeo, considerando a situação comunicativa, a organização específica da fala nesses gêneros e o tema/assunto/ finalidade dos textos.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP23', 'ef03lp23', 'Analisar o uso de adjetivos em cartas dirigidas a veículos da mídia impressa ou digital (cartas do leitor ou de reclamação a jornais ou revistas), digitais ou impressas.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP24', 'ef03lp24', 'Ler/ouvir e compreender, com autonomia, relatos de observações e de pesquisas em fontes de informações, considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP25', 'ef03lp25', 'Planejar e produzir textos para apresentar resultados de observações e de pesquisas em fontes de informações, incluindo, quando pertinente, imagens, diagramas e gráficos ou tabelas simples, considerando a situação comunicativa e o tema/assunto do texto.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP26', 'ef03lp26', 'Identificar e reproduzir, em relatórios de observação e pesquisa, a formatação e diagramação específica desses gêneros (passos ou listas de itens, tabelas, ilustrações, gráficos, resumo dos resultados), inclusive em suas versões orais.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03LP27', 'ef03lp27', 'Recitar cordel e cantar repentes e emboladas, observando as rimas e obedecendo ao ritmo e à melodia.', '3º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF03MA01', 'ef03ma01', 'Ler, escrever e comparar números naturais de até a ordem de unidade de milhar, estabelecendo relações entre os registros numéricos e em língua materna.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA02', 'ef03ma02', 'Identificar características do sistema de numeração decimal, utilizando a composição e a decomposição de número natural de até quatro ordens.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA03', 'ef03ma03', 'Construir e utilizar fatos básicos da adição e da multiplicação para o cálculo mental ou escrito.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA04', 'ef03ma04', 'Estabelecer a relação entre números naturais e pontos da reta numérica para utilizá-la na ordenação dos números naturais e também na construção de fatos da adição e da subtração, relacionando-os com deslocamentos para a direita ou para a esquerda.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA05', 'ef03ma05', 'Utilizar diferentes procedimentos de cálculo mental e escrito, inclusive os convencionais, para resolver problemas significativos envolvendo adição e subtração com números naturais.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA06', 'ef03ma06', 'Resolver e elaborar problemas de adição e subtração com os significados de juntar, acrescentar, separar, retirar, comparar e completar quantidades, utilizando diferentes estratégias de cálculo exato ou aproximado, incluindo cálculo mental.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA07', 'ef03ma07', 'Resolver e elaborar problemas de multiplicação (por 2, 3, 4, 5 e 10) com os significados de adição de parcelas iguais e elementos apresentados em disposição retangular, utilizando diferentes estratégias de cálculo e registros.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA08', 'ef03ma08', 'Resolver e elaborar problemas de divisão de um número natural por outro (até 10), com resto zero e com resto diferente de zero, com os significados de repartição equitativa e de medida, por meio de estratégias e registros pessoais.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA09', 'ef03ma09', 'Associar o quociente de uma divisão com resto zero de um número natural por 2, 3, 4, 5 e 10 às ideias de metade, terça, quarta, quinta e décima partes.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA10', 'ef03ma10', 'Identificar regularidades em sequências ordenadas de números naturais, resultantes da realização de adições ou subtrações sucessivas, por um mesmo número, descrever uma regra de formação da sequência e determinar elementos faltantes ou seguintes.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA11', 'ef03ma11', 'Compreender a ideia de igualdade para escrever diferentes sentenças de adições ou de subtrações de dois números naturais que resultem na mesma soma ou diferença.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA12', 'ef03ma12', 'Descrever e representar, por meio de esboços de trajetos ou utilizando croquis e maquetes, a movimentação de pessoas ou de objetos no espaço, incluindo mudanças de direção e sentido, com base em diferentes pontos de referência.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA13', 'ef03ma13', 'Associar figuras geométricas espaciais (cubo, bloco retangular, pirâmide, cone, cilindro e esfera) a objetos do mundo físico e nomear essas figuras.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA14', 'ef03ma14', 'Descrever características de algumas figuras geométricas espaciais (prismas retos, pirâmides, cilindros, cones), relacionando-as com suas planificações.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA15', 'ef03ma15', 'Classificar e comparar figuras planas (triângulo, quadrado, retângulo, trapézio e paralelogramo) em relação a seus lados (quantidade, posições relativas e comprimento) e vértices.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA16', 'ef03ma16', 'Reconhecer figuras congruentes, usando sobreposição e desenhos em malhas quadriculadas ou triangulares, incluindo o uso de tecnologias digitais.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA17', 'ef03ma17', 'Reconhecer que o resultado de uma medida depende da unidade de medida utilizada.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA18', 'ef03ma18', 'Escolher a unidade de medida e o instrumento mais apropriado para medições de comprimento, tempo e capacidade.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA19', 'ef03ma19', 'Estimar, medir e comparar comprimentos, utilizando unidades de medida não padronizadas e padronizadas mais usuais (metro, centímetro e milímetro) e diversos instrumentos de medida.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA20', 'ef03ma20', 'Estimar e medir capacidade e massa, utilizando unidades de medida não padronizadas e padronizadas mais usuais (litro, mililitro, quilograma, grama e miligrama), reconhecendo-as em leitura de rótulos e embalagens, entre outros.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA21', 'ef03ma21', 'Comparar, visualmente ou por superposição, áreas de faces de objetos, de figuras planas ou de desenhos.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA22', 'ef03ma22', 'Ler e registrar medidas e intervalos de tempo, utilizando relógios (analógico e digital) para informar os horários de início e término de realização de uma atividade e sua duração.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA23', 'ef03ma23', 'Ler horas em relógios digitais e em relógios analógicos e reconhecer a relação entre hora e minutos e entre minuto e segundos.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA24', 'ef03ma24', 'Resolver e elaborar problemas que envolvam a comparação e a equivalência de valores monetários do sistema brasileiro em situações de compra, venda e troca.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA25', 'ef03ma25', 'Identificar, em eventos familiares aleatórios, todos os resultados possíveis, estimando os que têm maiores ou menores chances de ocorrência.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA26', 'ef03ma26', 'Resolver problemas cujos dados estão apresentados em tabelas de dupla entrada, gráficos de barras ou de colunas.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA27', 'ef03ma27', 'Ler, interpretar e comparar dados apresentados em tabelas de dupla entrada, gráficos de barras ou de colunas, envolvendo resultados de pesquisas significativas, utilizando termos como maior e menor frequência, apropriando-se desse tipo de linguagem para compreender aspectos da realidade sociocultural significativos.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF03MA28', 'ef03ma28', 'Realizar pesquisa envolvendo variáveis categóricas em um universo de até 50 elementos, organizar os dados coletados utilizando listas, tabelas simples ou de dupla entrada e representá-los em gráficos de colunas simples, com e sem uso de tecnologias digitais.', '3º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04CI01', 'ef04ci01', 'Identificar misturas na vida diária, com base em suas propriedades físicas observáveis, reconhecendo sua composição.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI02', 'ef04ci02', 'Testar e relatar transformações nos materiais do dia a dia quando expostos a diferentes condições (aquecimento, resfriamento, luz e umidade).', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI03', 'ef04ci03', 'Concluir que algumas mudanças causadas por aquecimento ou resfriamento são reversíveis (como as mudanças de estado físico da água) e outras não (como o cozimento do ovo, a queima do papel etc.).', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI04', 'ef04ci04', 'Analisar e construir cadeias alimentares simples, reconhecendo a posição ocupada pelos seres vivos nessas cadeias e o papel do Sol como fonte primária de energia na produção de alimentos.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI05', 'ef04ci05', 'Descrever e destacar semelhanças e diferenças entre o ciclo da matéria e o fluxo de energia entre os componentes vivos e não vivos de um ecossistema.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI06', 'ef04ci06', 'Relacionar a participação de fungos e bactérias no processo de decomposição, reconhecendo a importância ambiental desse processo.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI07', 'ef04ci07', 'Verificar a participação de microrganismos na produção de alimentos, combustíveis, medicamentos, entre outros.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI08', 'ef04ci08', 'Propor, a partir do conhecimento das formas de transmissão de alguns microrganismos (vírus, bactérias e protozoários), atitudes e medidas adequadas para prevenção de doenças a eles associadas.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI09', 'ef04ci09', 'Identificar os pontos cardeais, com base no registro de diferentes posições relativas do Sol e da sombra de uma vara (gnômon).', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI10', 'ef04ci10', 'Comparar as indicações dos pontos cardeais resultantes da observação das sombras de uma vara (gnômon) com aquelas obtidas por meio de uma bússola.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CI11', 'ef04ci11', 'Associar os movimentos cíclicos da Lua e da Terra a períodos de tempo regulares e ao uso desse conhecimento para a construção de calendários em diferentes culturas.', '4º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF04CO01', 'ef04co01', 'Reconhecer objetos do mundo real e/ou digital que podem ser representados através de matrizes que estabelecem uma organização na qual cada componente está em uma posição definida por coordenadas, fazendo manipulações simples sobre estas representações.', '4º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF04CO02', 'ef04co02', 'Reconhecer objetos do mundo real e/ou digital que podem ser representados através de registros que estabelecem uma organização na qual cada componente é identificado por um nome, fazendo manipulações sobre estas representações.', '4º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF04CO03', 'ef04co03', 'Criar e simular algoritmos representados em linguagem oral, escrita ou pictográfica, que incluam sequências e repetições simples e aninhadas (iterações definidas e indefinidas), para resolver problemas de forma independente e em colaboração.', '4º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF04CO04', 'ef04co04', 'Entender que para guardar, manipular e transmitir dados deve-se codificá-los de alguma forma que seja compreendida pela máquina (formato digital).', '4º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF04CO05', 'ef04co05', 'Codificar diferentes informações para representação em computador (binária, ASCII, atributos de pixel, como RGB etc.).', '4º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF04CO06', 'ef04co06', 'Usar diferentes ferramentas computacionais para criação de conteúdo (textos, apresentações, vídeos etc.).', '4º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF04CO07', 'ef04co07', 'Demonstrar postura ética nas atividades de coleta, transferência, guarda e uso de dados.', '4º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF04CO08', 'ef04co08', 'Reconhecer a importância de verificar a confiabilidade das fontes de informações obtidas na Internet.', '4º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF04ER01', 'ef04er01', 'Identificar ritos presentes no cotidiano pessoal, familiar, escolar e comunitário.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER02', 'ef04er02', 'Identificar ritos e suas funções em diferentes manifestações e tradições religiosas.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER03', 'ef04er03', 'Caracterizar ritos de iniciação e de passagem em diversos grupos religiosos (nascimento, casamento e morte).', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER04', 'ef04er04', 'Identificar as diversas formas de expressão da espiritualidade (orações, cultos, gestos, cantos, dança, meditação) nas diferentes tradições religiosas.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER05', 'ef04er05', 'Identificar representações religiosas em diferentes expressões artísticas (pinturas, arquitetura, esculturas, ícones, símbolos, imagens), reconhecendo-as como parte da identidade de diferentes culturas e tradições religiosas.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER06', 'ef04er06', 'Identificar nomes, significados e representações de divindades nos contextos familiar e comunitário.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04ER07', 'ef04er07', 'Reconhecer e respeitar as ideias de divindades de diferentes manifestações e tradições religiosas.', '4º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF04GE01', 'ef04ge01', 'Selecionar, em seus lugares de vivência e em suas histórias familiares e/ou da comunidade, elementos de distintas culturas (indígenas, afro-brasileiras, de outras regiões do país, latino-americanas, europeias, asiáticas etc.), valorizando o que é próprio em cada uma delas e sua contribuição para a formação da cultura local, regional e brasileira.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE02', 'ef04ge02', 'Descrever processos migratórios e suas contribuições para a formação da sociedade brasileira.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE03', 'ef04ge03', 'Distinguir funções e papéis dos órgãos do poder público municipal e canais de participação social na gestão do Município, incluindo a Câmara de Vereadores e Conselhos Municipais.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE04', 'ef04ge04', 'Reconhecer especificidades e analisar a interdependência do campo e da cidade, considerando fluxos econômicos, de informações, de ideias e de pessoas.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE05', 'ef04ge05', 'Distinguir unidades político-administrativas oficiais nacionais (Distrito, Município, Unidade da Federação e grande região), suas fronteiras e sua hierarquia, localizando seus lugares de vivência.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE06', 'ef04ge06', 'Identificar e descrever territórios étnico-culturais existentes no Brasil, tais como terras indígenas e de comunidades remanescentes de quilombos, reconhecendo a legitimidade da demarcação desses territórios.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE07', 'ef04ge07', 'Comparar as características do trabalho no campo e na cidade.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE08', 'ef04ge08', 'Descrever e discutir o processo de produção (transformação de matérias-primas), circulação e consumo de diferentes produtos.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE09', 'ef04ge09', 'Utilizar as direções cardeais na localização de componentes físicos e humanos nas paisagens rurais e urbanas.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE10', 'ef04ge10', 'Comparar tipos variados de mapas, identificando suas características, elaboradores, finalidades, diferenças e semelhanças.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04GE11', 'ef04ge11', 'Identificar as características das paisagens naturais e antrópicas (relevo, cobertura vegetal, rios etc.) no ambiente em que vive, bem como a ação humana na conservação ou degradação dessas áreas.', '4º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF04HI01', 'ef04hi01', 'Reconhecer a história como resultado da ação do ser humano no tempo e no espaço, com base na identificação de mudanças e permanências ao longo do tempo.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI02', 'ef04hi02', 'Identificar mudanças e permanências ao longo do tempo, discutindo os sentidos dos grandes marcos da história da humanidade (nomadismo, desenvolvimento da agricultura e do pastoreio, criação da indústria etc.).', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI03', 'ef04hi03', 'Identificar as transformações ocorridas na cidade ao longo do tempo e discutir suas interferências nos modos de vida de seus habitantes, tomando como ponto de partida o presente.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI04', 'ef04hi04', 'Identificar as relações entre os indivíduos e a natureza e discutir o significado do nomadismo e da fixação das primeiras comunidades humanas.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI05', 'ef04hi05', 'Relacionar os processos de ocupação do campo a intervenções na natureza, avaliando os resultados dessas intervenções.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI06', 'ef04hi06', 'Identificar as transformações ocorridas nos processos de deslocamento das pessoas e mercadorias, analisando as formas de adaptação ou marginalização.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI07', 'ef04hi07', 'Identificar e descrever a importância dos caminhos terrestres, fluviais e marítimos para a dinâmica da vida comercial.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI08', 'ef04hi08', 'Identificar as transformações ocorridas nos meios de comunicação (cultura oral, imprensa, rádio, televisão, cinema, internet e demais tecnologias digitais de informação e comunicação) e discutir seus significados para os diferentes grupos ou estratos sociais.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI09', 'ef04hi09', 'Identificar as motivações dos processos migratórios em diferentes tempos e espaços e avaliar o papel desempenhado pela migração nas regiões de destino.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI10', 'ef04hi10', 'Analisar diferentes fluxos populacionais e suas contribuições para a formação da sociedade brasileira.', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04HI11', 'ef04hi11', 'Analisar, na sociedade em que vive, a existência ou não de mudanças associadas à migração (interna e internacional).', '4º ano(s) do Ensino Fundamental', 'História'),
  ('EF04LP01', 'ef04lp01', 'Grafar palavras utilizando regras de correspondência fonema-grafema regulares diretas e contextuais.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP02', 'ef04lp02', 'Ler e escrever, corretamente, palavras com sílabas VV e CVV em casos nos quais a combinação VV (ditongo) é reduzida na língua oral (ai, ei, ou).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP03', 'ef04lp03', 'Localizar palavras no dicionário para esclarecer significados, reconhecendo o significado mais plausível para o contexto que deu origem à consulta.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP04', 'ef04lp04', 'Usar acento gráfico (agudo ou circunflexo) em paroxítonas terminadas em -i(s), -l, -r, -ão(s).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP05', 'ef04lp05', 'Identificar a função na leitura e usar, adequadamente, na escrita ponto final, de interrogação, de exclamação, dois-pontos e travessão em diálogos (discurso direto), vírgula em enumerações e em separação de vocativo e de aposto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP06', 'ef04lp06', 'Identificar em textos e usar na produção textual a concordância entre substantivo ou pronome pessoal e verbo (concordância verbal).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP07', 'ef04lp07', 'Identificar em textos e usar na produção textual a concordância entre artigo, substantivo e adjetivo (concordância no grupo nominal).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP08', 'ef04lp08', 'Reconhecer e grafar, corretamente, palavras derivadas com os sufixos -agem, -oso, -eza, -izar/-isar (regulares morfológicas).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP09', 'ef04lp09', 'Ler e compreender, com autonomia, boletos, faturas e carnês, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero (campos, itens elencados, medidas de consumo, código de barras) e considerando a situação comunicativa e a finalidade do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP10', 'ef04lp10', 'Ler e compreender, com autonomia, cartas pessoais de reclamação, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero carta e considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP11', 'ef04lp11', 'Planejar e produzir, com autonomia, cartas pessoais de reclamação, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero carta e com a estrutura própria desses textos (problema, opinião, argumentos), considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP12', 'ef04lp12', 'Assistir, em vídeo digital, a programa infantil com instruções de montagem, de jogos e brincadeiras e, a partir dele, planejar e produzir tutoriais em áudio ou vídeo.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP13', 'ef04lp13', 'Identificar e reproduzir, em textos injuntivos instrucionais (instruções de jogos digitais ou impressos), a formatação própria desses textos (verbos imperativos, indicação de passos a ser seguidos) e formato específico dos textos orais ou escritos desses gêneros (lista/ apresentação de materiais e instruções/passos de jogo).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP14', 'ef04lp14', 'Identificar, em notícias, fatos, participantes, local e momento/tempo da ocorrência do fato noticiado.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP15', 'ef04lp15', 'Distinguir fatos de opiniões/sugestões em textos (informativos, jornalísticos, publicitários etc.).', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP16', 'ef04lp16', 'Produzir notícias sobre fatos ocorridos no universo escolar, digitais ou impressas, para o jornal da escola, noticiando os fatos e seus atores e comentando decorrências, de acordo com as convenções do gênero notícia e considerando a situação comunicativa e o tema/assunto do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP17', 'ef04lp17', 'Produzir jornais radiofônicos ou televisivos e entrevistas veiculadas em rádio, TV e na internet, orientando-se por roteiro ou texto e demonstrando conhecimento dos gêneros jornal falado/televisivo e entrevista.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP18', 'ef04lp18', 'Analisar o padrão entonacional e a expressão facial e corporal de âncoras de jornais radiofônicos ou televisivos e de entrevistadores/entrevistados.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP19', 'ef04lp19', 'Ler e compreender textos expositivos de divulgação científica para crianças, considerando a situação comunicativa e o tema/ assunto do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP20', 'ef04lp20', 'Reconhecer a função de gráficos, diagramas e tabelas em textos, como forma de apresentação de dados e informações.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP21', 'ef04lp21', 'Planejar e produzir textos sobre temas de interesse, com base em resultados de observações e pesquisas em fontes de informações impressas ou eletrônicas, incluindo, quando pertinente, imagens e gráficos ou tabelas simples, considerando a situação comunicativa e o tema/assunto do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP22', 'ef04lp22', 'Planejar e produzir, com certa autonomia, verbetes de enciclopédia infantil, digitais ou impressos, considerando a situação comunicativa e o tema/ assunto/finalidade do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP23', 'ef04lp23', 'Identificar e reproduzir, em verbetes de enciclopédia infantil, digitais ou impressos, a formatação e diagramação específica desse gênero (título do verbete, definição, detalhamento, curiosidades), considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP24', 'ef04lp24', 'Identificar e reproduzir, em seu formato, tabelas, diagramas e gráficos em relatórios de observação e pesquisa, como forma de apresentação de dados e informações.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP25', 'ef04lp25', 'Representar cenas de textos dramáticos, reproduzindo as falas das personagens, de acordo com as rubricas de interpretação e movimento indicadas pelo autor.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP26', 'ef04lp26', 'Observar, em poemas concretos, o formato, a distribuição e a diagramação das letras do texto na página.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04LP27', 'ef04lp27', 'Identificar, em textos dramáticos, marcadores das falas das personagens e de cena.', '4º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF04MA01', 'ef04ma01', 'Ler, escrever e ordenar números naturais até a ordem de dezenas de milhar.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA02', 'ef04ma02', 'Mostrar, por decomposição e composição, que todo número natural pode ser escrito por meio de adições e multiplicações por potências de dez, para compreender o sistema de numeração decimal e desenvolver estratégias de cálculo.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA03', 'ef04ma03', 'Resolver e elaborar problemas com números naturais envolvendo adição e subtração, utilizando estratégias diversas, como cálculo, cálculo mental e algoritmos, além de fazer estimativas do resultado.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA04', 'ef04ma04', 'Utilizar as relações entre adição e subtração, bem como entre multiplicação e divisão, para ampliar as estratégias de cálculo.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA05', 'ef04ma05', 'Utilizar as propriedades das operações para desenvolver estratégias de cálculo.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA06', 'ef04ma06', 'Resolver e elaborar problemas envolvendo diferentes significados da multiplicação (adição de parcelas iguais, organização retangular e proporcionalidade), utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA07', 'ef04ma07', 'Resolver e elaborar problemas de divisão cujo divisor tenha no máximo dois algarismos, envolvendo os significados de repartição equitativa e de medida, utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA08', 'ef04ma08', 'Resolver, com o suporte de imagem e/ou material manipulável, problemas simples de contagem, como a determinação do número de agrupamentos possíveis ao se combinar cada elemento de uma coleção com todos os elementos de outra, utilizando estratégias e formas de registro pessoais.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA09', 'ef04ma09', 'Reconhecer as frações unitárias mais usuais (1/2, 1/3, 1/4, 1/5, 1/10 e 1/100) como unidades de medida menores do que uma unidade, utilizando a reta numérica como recurso.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA10', 'ef04ma10', 'Reconhecer que as regras do sistema de numeração decimal podem ser estendidas para a representação decimal de um número racional e relacionar décimos e centésimos com a representação do sistema monetário brasileiro.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA11', 'ef04ma11', 'Identificar regularidades em sequências numéricas compostas por múltiplos de um número natural.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA12', 'ef04ma12', 'Reconhecer, por meio de investigações, que há grupos de números naturais para os quais as divisões por um determinado número resultam em restos iguais, identificando regularidades.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA13', 'ef04ma13', 'Reconhecer, por meio de investigações, utilizando a calculadora quando necessário, as relações inversas entre as operações de adição e de subtração e de multiplicação e de divisão, para aplicá-las na resolução de problemas.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA14', 'ef04ma14', 'Reconhecer e mostrar, por meio de exemplos, que a relação de igualdade existente entre dois termos permanece quando se adiciona ou se subtrai um mesmo número a cada um desses termos.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA15', 'ef04ma15', 'Determinar o número desconhecido que torna verdadeira uma igualdade que envolve as operações fundamentais com números naturais.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA16', 'ef04ma16', 'Descrever deslocamentos e localização de pessoas e de objetos no espaço, por meio de malhas quadriculadas e representações como desenhos, mapas, planta baixa e croquis, empregando termos como direita e esquerda, mudanças de direção e sentido, intersecção, transversais, paralelas e perpendiculares.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA17', 'ef04ma17', 'Associar prismas e pirâmides a suas planificações e analisar, nomear e comparar seus atributos, estabelecendo relações entre as representações planas e espaciais.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA18', 'ef04ma18', 'Reconhecer ângulos retos e não retos em figuras poligonais com o uso de dobraduras, esquadros ou softwares de geometria.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA19', 'ef04ma19', 'Reconhecer simetria de reflexão em figuras e em pares de figuras geométricas planas e utilizá-la na construção de figuras congruentes, com o uso de malhas quadriculadas e de softwares de geometria.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA20', 'ef04ma20', 'Medir e estimar comprimentos (incluindo perímetros), massas e capacidades, utilizando unidades de medida padronizadas mais usuais, valorizando e respeitando a cultura local.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA21', 'ef04ma21', 'Medir, comparar e estimar área de figuras planas desenhadas em malha quadriculada, pela contagem dos quadradinhos ou de metades de quadradinho, reconhecendo que duas figuras com formatos diferentes podem ter a mesma medida de área.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA22', 'ef04ma22', 'Ler e registrar medidas e intervalos de tempo em horas, minutos e segundos em situações relacionadas ao seu cotidiano, como informar os horários de início e término de realização de uma tarefa e sua duração.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA23', 'ef04ma23', 'Reconhecer temperatura como grandeza e o grau Celsius como unidade de medida a ela associada e utilizá-lo em comparações de temperaturas em diferentes regiões do Brasil ou no exterior ou, ainda, em discussões que envolvam problemas relacionados ao aquecimento global.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA24', 'ef04ma24', 'Registrar as temperaturas máxima e mínima diárias, em locais do seu cotidiano, e elaborar gráficos de colunas com as variações diárias da temperatura, utilizando, inclusive, planilhas eletrônicas.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA25', 'ef04ma25', 'Resolver e elaborar problemas que envolvam situações de compra e venda e formas de pagamento, utilizando termos como troco e desconto, enfatizando o consumo ético, consciente e responsável.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA26', 'ef04ma26', 'Identificar, entre eventos aleatórios cotidianos, aqueles que têm maior chance de ocorrência, reconhecendo características de resultados mais prováveis, sem utilizar frações.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA27', 'ef04ma27', 'Analisar dados apresentados em tabelas simples ou de dupla entrada e em gráficos de colunas ou pictóricos, com base em informações das diferentes áreas do conhecimento, e produzir texto com a síntese de sua análise.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF04MA28', 'ef04ma28', 'Realizar pesquisa envolvendo variáveis categóricas e numéricas e organizar dados coletados por meio de tabelas e gráficos de colunas simples ou agrupadas, com e sem uso de tecnologias digitais.', '4º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05CI01', 'ef05ci01', 'Explorar fenômenos da vida cotidiana que evidenciem propriedades físicas dos materiais – como densidade, condutibilidade térmica e elétrica, respostas a forças magnéticas, solubilidade, respostas a forças mecânicas (dureza, elasticidade etc.), entre outras.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI02', 'ef05ci02', 'Aplicar os conhecimentos sobre as mudanças de estado físico da água para explicar o ciclo hidrológico e analisar suas implicações na agricultura, no clima, na geração de energia elétrica, no provimento de água potável e no equilíbrio dos ecossistemas regionais (ou locais).', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI03', 'ef05ci03', 'Selecionar argumentos que justifiquem a importância da cobertura vegetal para a manutenção do ciclo da água, a conservação dos solos, dos cursos de água e da qualidade do ar atmosférico.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI04', 'ef05ci04', 'Identificar os principais usos da água e de outros materiais nas atividades cotidianas para discutir e propor formas sustentáveis de utilização desses recursos.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI05', 'ef05ci05', 'Construir propostas coletivas para um consumo mais consciente e criar soluções tecnológicas para o descarte adequado e a reutilização ou reciclagem de materiais consumidos na escola e/ou na vida cotidiana.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI06', 'ef05ci06', 'Selecionar argumentos que justifiquem por que os sistemas digestório e respiratório são considerados corresponsáveis pelo processo de nutrição do organismo, com base na identificação das funções desses sistemas.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI07', 'ef05ci07', 'Justificar a relação entre o funcionamento do sistema circulatório, a distribuição dos nutrientes pelo organismo e a eliminação dos resíduos produzidos.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI08', 'ef05ci08', 'Organizar um cardápio equilibrado com base nas características dos grupos alimentares (nutrientes e calorias) e nas necessidades individuais (atividades realizadas, idade, sexo etc.) para a manutenção da saúde do organismo.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI09', 'ef05ci09', 'Discutir a ocorrência de distúrbios nutricionais (como obesidade, subnutrição etc.) entre crianças e jovens a partir da análise de seus hábitos (tipos e quantidade de alimento ingerido, prática de atividade física etc.).', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI10', 'ef05ci10', 'Identificar algumas constelações no céu, com o apoio de recursos (como mapas celestes e aplicativos digitais, entre outros), e os períodos do ano em que elas são visíveis no início da noite.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI11', 'ef05ci11', 'Associar o movimento diário do Sol e das demais estrelas no céu ao movimento de rotação da Terra.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI12', 'ef05ci12', 'Concluir sobre a periodicidade das fases da Lua, com base na observação e no registro das formas aparentes da Lua no céu ao longo de, pelo menos, dois meses.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CI13', 'ef05ci13', 'Projetar e construir dispositivos para observação à distância (luneta, periscópio etc.), para observação ampliada de objetos (lupas, microscópios) ou para registro de imagens (máquinas fotográficas) e discutir usos sociais desses dispositivos.', '5º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF05CO01', 'ef05co01', 'Reconhecer objetos do mundo real e/ou digital que podem ser representados através de listas que estabelecem uma organização na qual há um número variável de itens dispostos em sequência, fazendo manipulações simples sobre estas representações.', '5º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF05CO02', 'ef05co02', 'Reconhecer objetos do mundo real e digital que podem ser representados através de grafos que estabelecem uma organização com uma quantidade variável de vértices conectados por arestas, fazendo manipulações simples sobre estas representações.', '5º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF05CO03', 'ef05co03', 'Realizar operações de negação, conjunção e disjunção sobre sentenças lógicas e valores ''verdadeiro'' e ''falso''.', '5º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF05CO04', 'ef05co04', 'Criar e simular algoritmos representados em linguagem oral, escrita ou pictográfica, que incluam sequências, repetições e seleções condicionais para resolver problemas de forma independente e em colaboração.', '5º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF05CO05', 'ef05co05', 'Identificar os componentes principais de um computador (dispositivos de entrada/saída, processadores e armazenamento).', '5º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF05CO06', 'ef05co06', 'Reconhecer que os dados podem ser armazenados em um dispositivo local ou remoto.', '5º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF05CO07', 'ef05co07', 'Reconhecer a necessidade de um sistema operacional para a execução de programas e gerenciamento do hardware.', '5º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF05CO08', 'ef05co08', 'Acessar as informações na Internet de forma crítica para distinguir os conteúdos confiáveis de não confiáveis.', '5º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF05CO09', 'ef05co09', 'Usar informações considerando aplicações e limites dos direitos autorais em diferentes mídias digitais.', '5º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF05CO10', 'ef05co10', 'Expressar-se crítica e criativamente na compreensão das mudanças tecnológicas no mundo do trabalho e sobre a evolução da sociedade.', '5º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF05CO11', 'ef05co11', 'Identificar a adequação de diferentes tecnologias computacionais na resolução de problemas.', '5º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF05ER01', 'ef05er01', 'Identificar e respeitar acontecimentos sagrados de diferentes culturas e tradições religiosas como recurso para preservar a memória.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER02', 'ef05er02', 'Identificar mitos de criação em diferentes culturas e tradições religiosas.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER03', 'ef05er03', 'Reconhecer funções e mensagens religiosas contidas nos mitos de criação (concepções de mundo, natureza, ser humano, divindades, vida e morte).', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER04', 'ef05er04', 'Reconhecer a importância da tradição oral para preservar memórias e acontecimentos religiosos.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER05', 'ef05er05', 'Identificar elementos da tradição oral nas culturas e religiosidades indígenas, afro-brasileiras, ciganas, entre outras.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER06', 'ef05er06', 'Identificar o papel dos sábios e anciãos na comunicação e preservação da tradição oral.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05ER07', 'ef05er07', 'Reconhecer, em textos orais, ensinamentos relacionados a modos de ser e viver.', '5º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF05GE01', 'ef05ge01', 'Descrever e analisar dinâmicas populacionais na Unidade da Federação em que vive, estabelecendo relações entre migrações e condições de infraestrutura.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE02', 'ef05ge02', 'Identificar diferenças étnico-raciais e étnico-culturais e desigualdades sociais entre grupos em diferentes territórios.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE03', 'ef05ge03', 'Identificar as formas e funções das cidades e analisar as mudanças sociais, econômicas e ambientais provocadas pelo seu crescimento.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE04', 'ef05ge04', 'Reconhecer as características da cidade e analisar as interações entre a cidade e o campo e entre cidades na rede urbana.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE05', 'ef05ge05', 'Identificar e comparar as mudanças dos tipos de trabalho e desenvolvimento tecnológico na agropecuária, na indústria, no comércio e nos serviços.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE06', 'ef05ge06', 'Identificar e comparar transformações dos meios de transporte e de comunicação.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE07', 'ef05ge07', 'Identificar os diferentes tipos de energia utilizados na produção industrial, agrícola e extrativa e no cotidiano das populações.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE08', 'ef05ge08', 'Analisar transformações de paisagens nas cidades, comparando sequência de fotografias, fotografias aéreas e imagens de satélite de épocas diferentes.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE09', 'ef05ge09', 'Estabelecer conexões e hierarquias entre diferentes cidades, utilizando mapas temáticos e representações gráficas.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE10', 'ef05ge10', 'Reconhecer e comparar atributos da qualidade ambiental e algumas formas de poluição dos cursos de água e dos oceanos (esgotos, efluentes industriais, marés negras etc.).', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE11', 'ef05ge11', 'Identificar e descrever problemas ambientais que ocorrem no entorno da escola e da residência (lixões, indústrias poluentes, destruição do patrimônio histórico etc.), propondo soluções (inclusive tecnológicas) para esses problemas.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05GE12', 'ef05ge12', 'Identificar órgãos do poder público e canais de participação social responsáveis por buscar soluções para a melhoria da qualidade de vida (em áreas como meio ambiente, mobilidade, moradia e direito à cidade) e discutir as propostas implementadas por esses órgãos que afetam a comunidade em que vive.', '5º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF05HI01', 'ef05hi01', 'Identificar os processos de formação das culturas e dos povos, relacionando-os com o espaço geográfico ocupado.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI02', 'ef05hi02', 'Identificar os mecanismos de organização do poder político com vistas à compreensão da ideia de Estado e/ou de outras formas de ordenação social.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI03', 'ef05hi03', 'Analisar o papel das culturas e das religiões na composição identitária dos povos antigos.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI04', 'ef05hi04', 'Associar a noção de cidadania com os princípios de respeito à diversidade, à pluralidade e aos direitos humanos.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI05', 'ef05hi05', 'Associar o conceito de cidadania à conquista de direitos dos povos e das sociedades, compreendendo-o como conquista histórica.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI06', 'ef05hi06', 'Comparar o uso de diferentes linguagens e tecnologias no processo de comunicação e avaliar os significados sociais, políticos e culturais atribuídos a elas.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI07', 'ef05hi07', 'Identificar os processos de produção, hierarquização e difusão dos marcos de memória e discutir a presença e/ou a ausência de diferentes grupos que compõem a sociedade na nomeação desses marcos de memória.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI08', 'ef05hi08', 'Identificar formas de marcação da passagem do tempo em distintas sociedades, incluindo os povos indígenas originários e os povos africanos.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI09', 'ef05hi09', 'Comparar pontos de vista sobre temas que impactam a vida cotidiana no tempo presente, por meio do acesso a diferentes fontes, incluindo orais.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05HI10', 'ef05hi10', 'Inventariar os patrimônios materiais e imateriais da humanidade e analisar mudanças e permanências desses patrimônios ao longo do tempo.', '5º ano(s) do Ensino Fundamental', 'História'),
  ('EF05LP01', 'ef05lp01', 'Grafar palavras utilizando regras de correspondência fonema-grafema regulares, contextuais e morfológicas e palavras de uso frequente com correspondências irregulares.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP02', 'ef05lp02', 'Identificar o caráter polissêmico das palavras (uma mesma palavra com diferentes significados, de acordo com o contexto de uso), comparando o significado de determinados termos utilizados nas áreas científicas com esses mesmos termos utilizados na linguagem usual.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP03', 'ef05lp03', 'Acentuar corretamente palavras oxítonas, paroxítonas e proparoxítonas.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP04', 'ef05lp04', 'Diferenciar, na leitura de textos, vírgula, ponto e vírgula, dois-pontos e reconhecer, na leitura de textos, o efeito de sentido que decorre do uso de reticências, aspas, parênteses.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP05', 'ef05lp05', 'Identificar a expressão de presente, passado e futuro em tempos verbais do modo indicativo.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP06', 'ef05lp06', 'Flexionar, adequadamente, na escrita e na oralidade, os verbos em concordância com pronomes pessoais/nomes sujeitos da oração.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP07', 'ef05lp07', 'Identificar, em textos, o uso de conjunções e a relação que estabelecem entre partes do texto: adição, oposição, tempo, causa, condição, finalidade.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP08', 'ef05lp08', 'Diferenciar palavras primitivas, derivadas e compostas, e derivadas por adição de prefixo e de sufixo.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP09', 'ef05lp09', 'Ler e compreender, com autonomia, textos instrucional de regras de jogo, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero e considerando a situação comunicativa e a finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP10', 'ef05lp10', 'Ler e compreender, com autonomia, anedotas, piadas e cartuns, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero e considerando a situação comunicativa e a finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP11', 'ef05lp11', 'Registrar, com autonomia, anedotas, piadas e cartuns, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero e considerando a situação comunicativa e a finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP12', 'ef05lp12', 'Planejar e produzir, com autonomia, textos instrucionais de regras de jogo, dentre outros gêneros do campo da vida cotidiana, de acordo com as convenções do gênero e considerando a situação comunicativa e a finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP13', 'ef05lp13', 'Assistir, em vídeo digital, a postagem de vlog infantil de críticas de brinquedos e livros de literatura infantil e, a partir dele, planejar e produzir resenhas digitais em áudio ou vídeo.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP14', 'ef05lp14', 'Identificar e reproduzir, em textos de resenha crítica de brinquedos ou livros de literatura infantil, a formatação própria desses textos (apresentação e avaliação do produto).', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP15', 'ef05lp15', 'Ler/assistir e compreender, com autonomia, notícias, reportagens, vídeos em vlogs argumentativos, dentre outros gêneros do campo político-cidadão, de acordo com as convenções dos gêneros e considerando a situação comunicativa e o tema/assunto do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP16', 'ef05lp16', 'Comparar informações sobre um mesmo fato veiculadas em diferentes mídias e concluir sobre qual é mais confiável e por quê.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP17', 'ef05lp17', 'Produzir roteiro para edição de uma reportagem digital sobre temas de interesse da turma, a partir de buscas de informações, imagens, áudios e vídeos na internet, de acordo com as convenções do gênero e considerando a situação comunicativa e o tema/assunto do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP18', 'ef05lp18', 'Roteirizar, produzir e editar vídeo para vlogs argumentativos sobre produtos de mídia para público infantil (filmes, desenhos animados, HQs, games etc.), com base em conhecimentos sobre os mesmos, de acordo com as convenções do gênero e considerando a situação comunicativa e o tema/ assunto/finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP19', 'ef05lp19', 'Argumentar oralmente sobre acontecimentos de interesse social, com base em conhecimentos sobre fatos divulgados em TV, rádio, mídia impressa e digital, respeitando pontos de vista diferentes.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP20', 'ef05lp20', 'Analisar a validade e força de argumentos em argumentações sobre produtos de mídia para público infantil (filmes, desenhos animados, HQs, games etc.), com base em conhecimentos sobre os mesmos.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP21', 'ef05lp21', 'Analisar o padrão entonacional, a expressão facial e corporal e as escolhas de variedade e registro linguísticos de vloggers de vlogs opinativos ou argumentativos.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP22', 'ef05lp22', 'Ler e compreender verbetes de dicionário, identificando a estrutura, as informações gramaticais (significado de abreviaturas) e as informações semânticas.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP23', 'ef05lp23', 'Comparar informações apresentadas em gráficos ou tabelas.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP24', 'ef05lp24', 'Planejar e produzir texto sobre tema de interesse, organizando resultados de pesquisa em fontes de informação impressas ou digitais, incluindo imagens e gráficos ou tabelas, considerando a situação comunicativa e o tema/assunto do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP25', 'ef05lp25', 'Planejar e produzir, com certa autonomia, verbetes de dicionário, digitais ou impressos, considerando a situação comunicativa e o tema/assunto/finalidade do texto.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP26', 'ef05lp26', 'Utilizar, ao produzir o texto, conhecimentos linguísticos e gramaticais: regras sintáticas de concordância nominal e verbal, convenções de escrita de citações, pontuação (ponto final, dois-pontos, vírgulas em enumerações) e regras ortográficas.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP27', 'ef05lp27', 'Utilizar, ao produzir o texto, recursos de coesão pronominal (pronomes anafóricos) e articuladores de relações de sentido (tempo, causa, oposição, conclusão, comparação), com nível adequado de informatividade.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05LP28', 'ef05lp28', 'Observar, em ciberpoemas e minicontos infantis em mídia digital, os recursos multissemióticos presentes nesses textos digitais.', '5º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF05MA01', 'ef05ma01', 'Ler, escrever e ordenar números naturais até a ordem das centenas de milhar com compreensão das principais características do sistema de numeração decimal.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA02', 'ef05ma02', 'Ler, escrever e ordenar números racionais na forma decimal com compreensão das principais características do sistema de numeração decimal, utilizando, como recursos, a composição e decomposição e a reta numérica.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA03', 'ef05ma03', 'Identificar e representar frações (menores e maiores que a unidade), associando-as ao resultado de uma divisão ou à ideia de parte de um todo, utilizando a reta numérica como recurso.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA04', 'ef05ma04', 'Identificar frações equivalentes.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA05', 'ef05ma05', 'Comparar e ordenar números racionais positivos (representações fracionária e decimal), relacionando-os a pontos na reta numérica.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA06', 'ef05ma06', 'Associar as representações 10%, 25%, 50%, 75% e 100% respectivamente à décima parte, quarta parte, metade, três quartos e um inteiro, para calcular porcentagens, utilizando estratégias pessoais, cálculo mental e calculadora, em contextos de educação financeira, entre outros.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA07', 'ef05ma07', 'Resolver e elaborar problemas de adição e subtração com números naturais e com números racionais, cuja representação decimal seja finita, utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA08', 'ef05ma08', 'Resolver e elaborar problemas de multiplicação e divisão com números naturais e com números racionais cuja representação decimal é finita (com multiplicador natural e divisor natural e diferente de zero), utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA09', 'ef05ma09', 'Resolver e elaborar problemas simples de contagem envolvendo o princípio multiplicativo, como a determinação do número de agrupamentos possíveis ao se combinar cada elemento de uma coleção com todos os elementos de outra coleção, por meio de diagramas de árvore ou por tabelas.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA10', 'ef05ma10', 'Concluir, por meio de investigações, que a relação de igualdade existente entre dois membros permanece ao adicionar, subtrair, multiplicar ou dividir cada um desses membros por um mesmo número, para construir a noção de equivalência.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA11', 'ef05ma11', 'Resolver e elaborar problemas cuja conversão em sentença matemática seja uma igualdade com uma operação em que um dos termos é desconhecido.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA12', 'ef05ma12', 'Resolver problemas que envolvam variação de proporcionalidade direta entre duas grandezas, para associar a quantidade de um produto ao valor a pagar, alterar as quantidades de ingredientes de receitas, ampliar ou reduzir escala em mapas, entre outros.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA13', 'ef05ma13', 'Resolver problemas envolvendo a partilha de uma quantidade em duas partes desiguais, tais como dividir uma quantidade em duas partes, de modo que uma seja o dobro da outra, com compreensão da ideia de razão entre as partes e delas com o todo.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA14', 'ef05ma14', 'Utilizar e compreender diferentes representações para a localização de objetos no plano, como mapas, células em planilhas eletrônicas e coordenadas geográficas, a fim de desenvolver as primeiras noções de coordenadas cartesianas.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA15', 'ef05ma15', 'Interpretar, descrever e representar a localização ou movimentação de objetos no plano cartesiano (1º quadrante), utilizando coordenadas cartesianas, indicando mudanças de direção e de sentido e giros.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA16', 'ef05ma16', 'Associar figuras espaciais a suas planificações (prismas, pirâmides, cilindros e cones) e analisar, nomear e comparar seus atributos.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA17', 'ef05ma17', 'Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e desenhá-los, utilizando material de desenho ou tecnologias digitais.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA18', 'ef05ma18', 'Reconhecer a congruência dos ângulos e a proporcionalidade entre os lados correspondentes de figuras poligonais em situações de ampliação e de redução em malhas quadriculadas e usando tecnologias digitais.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA19', 'ef05ma19', 'Resolver e elaborar problemas envolvendo medidas das grandezas comprimento, área, massa, tempo, temperatura e capacidade, recorrendo a transformações entre as unidades mais usuais em contextos socioculturais.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA20', 'ef05ma20', 'Concluir, por meio de investigações, que figuras de perímetros iguais podem ter áreas diferentes e que, também, figuras que têm a mesma área podem ter perímetros diferentes.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA21', 'ef05ma21', 'Reconhecer volume como grandeza associada a sólidos geométricos e medir volumes por meio de empilhamento de cubos, utilizando, preferencialmente, objetos concretos.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA22', 'ef05ma22', 'Apresentar todos os possíveis resultados de um experimento aleatório, estimando se esses resultados são igualmente prováveis ou não.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA23', 'ef05ma23', 'Determinar a probabilidade de ocorrência de um resultado em eventos aleatórios, quando todos os resultados possíveis têm a mesma chance de ocorrer (equiprováveis).', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA24', 'ef05ma24', 'Interpretar dados estatísticos apresentados em textos, tabelas e gráficos (colunas ou linhas), referentes a outras áreas do conhecimento ou a outros contextos, como saúde e trânsito, e produzir textos com o objetivo de sintetizar conclusões.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF05MA25', 'ef05ma25', 'Realizar pesquisa envolvendo variáveis categóricas e numéricas, organizar dados coletados por meio de tabelas, gráficos de colunas, pictóricos e de linhas, com e sem uso de tecnologias digitais, e apresentar texto escrito sobre a finalidade da pesquisa e a síntese dos resultados.', '5º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06CI01', 'ef06ci01', 'Classificar como homogênea ou heterogênea a mistura de dois ou mais materiais (água e sal, água e óleo, água e areia etc.).', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI02', 'ef06ci02', 'Identificar evidências de transformações químicas a partir do resultado de misturas de materiais que originam produtos diferentes dos que foram misturados (mistura de ingredientes para fazer um bolo, mistura de vinagre com bicarbonato de sódio etc.).', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI03', 'ef06ci03', 'Selecionar métodos mais adequados para a separação de diferentes sistemas heterogêneos a partir da identificação de processos de separação de materiais (como a produção de sal de cozinha, a destilação de petróleo, entre outros).', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI04', 'ef06ci04', 'Associar a produção de medicamentos e outros materiais sintéticos ao desenvolvimento científico e tecnológico, reconhecendo benefícios e avaliando impactos socioambientais.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI05', 'ef06ci05', 'Explicar a organização básica das células e seu papel como unidade estrutural e funcional dos seres vivos.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI06', 'ef06ci06', 'Concluir, com base na análise de ilustrações e/ou modelos (físicos ou digitais), que os organismos são um complexo arranjo de sistemas com diferentes níveis de organização.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI07', 'ef06ci07', 'Justificar o papel do sistema nervoso na coordenação das ações motoras e sensoriais do corpo, com base na análise de suas estruturas básicas e respectivas funções.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI08', 'ef06ci08', 'Explicar a importância da visão (captação e interpretação das imagens) na interação do organismo com o meio e, com base no funcionamento do olho humano, selecionar lentes adequadas para a correção de diferentes defeitos da visão.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI09', 'ef06ci09', 'Deduzir que a estrutura, a sustentação e a movimentação dos animais resultam da interação entre os sistemas muscular, ósseo e nervoso.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI10', 'ef06ci10', 'Explicar como o funcionamento do sistema nervoso pode ser afetado por substâncias psicoativas.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI11', 'ef06ci11', 'Identificar as diferentes camadas que estruturam o planeta Terra (da estrutura interna à atmosfera) e suas principais características.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI12', 'ef06ci12', 'Identificar diferentes tipos de rocha, relacionando a formação de fósseis a rochas sedimentares em diferentes períodos geológicos.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI13', 'ef06ci13', 'Selecionar argumentos e evidências que demonstrem a esfericidade da Terra.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CI14', 'ef06ci14', 'Inferir que as mudanças na sombra de uma vara (gnômon) ao longo do dia em diferentes períodos do ano são uma evidência dos movimentos relativos entre a Terra e o Sol, que podem ser explicados por meio dos movimentos de rotação e translação da Terra e da inclinação de seu eixo de rotação em relação ao plano de sua órbita em torno do Sol.', '6º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF06CO01', 'ef06co01', 'Classificar informações, agrupando-as em coleções (conjuntos) e associando cada coleção a um ‘tipo de dados’', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO02', 'ef06co02', 'Elaborar algoritmos que envolvam instruções sequenciais, de repetição e de seleção usando uma linguagem de programação.', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO03', 'ef06co03', 'Descrever com precisão a solução de um problema, construindo o programa que implementa a solução descrita.', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO04', 'ef06co04', 'Construir soluções de problemas usando a técnica de decomposição e automatizar tais soluções usando uma linguagem de programação.', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO05', 'ef06co05', 'Identificar os recursos ou insumos necessários (entradas) para a resolução de problemas, bem como os resultados esperados (saídas), determinando os respectivos tipos de dados, e estabelecendo a definição de problema como uma relação entre entrada e saída.', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO06', 'ef06co06', 'Comparar diferentes casos particulares (instâncias) de um mesmo problema, identificando as semelhanças e diferenças entre eles, e criar um algoritmo para resolver todos, fazendo uso de variáveis (parâmetros) para permitir o tratamento de todos os casos de forma genérica.', '6º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF06CO07', 'ef06co07', 'Entender o processo de transmissão de dados, como a informação é quebrada em pedaços, transmitida em pacotes através de múltiplos equipamentos, e reconstruída no destino.', '6º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF06CO08', 'ef06co08', 'Compreender e utilizar diferentes formas de armazenar, manipular, compactar e recuperar arquivos, documentos e metadados.', '6º ano(s) do Ensino Fundamental', 'Computação — Mundo Digital'),
  ('EF06CO09', 'ef06co09', 'Apresentar conduta e linguagem apropriadas ao se comunicar em ambiente digital, considerando a ética e o respeito.', '6º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF06CO10', 'ef06co10', 'Analisar o consumo de tecnologia na sociedade, compreendendo criticamente o caminho da produção dos recursos bem como aspectos ligados à obsolescência e a sustentabilidade.', '6º ano(s) do Ensino Fundamental', 'Computação — Cultura Digital'),
  ('EF06ER01', 'ef06er01', 'Reconhecer o papel da tradição escrita na preservação de memórias, acontecimentos e ensinamentos religiosos.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER02', 'ef06er02', 'Reconhecer e valorizar a diversidade de textos religiosos escritos (textos do Budismo, Cristianismo, Espiritismo, Hinduísmo, Islamismo, Judaísmo, entre outros).', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER03', 'ef06er03', 'Reconhecer, em textos escritos, ensinamentos relacionados a modos de ser e viver.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER04', 'ef06er04', 'Reconhecer que os textos escritos são utilizados pelas tradições religiosas de maneiras diversas.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER05', 'ef06er05', 'Discutir como o estudo e a interpretação dos textos religiosos influenciam os adeptos a vivenciarem os ensinamentos das tradições religiosas.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER06', 'ef06er06', 'Reconhecer a importância dos mitos, ritos, símbolos e textos na estruturação das diferentes crenças, tradições e movimentos religiosos.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06ER07', 'ef06er07', 'Exemplificar a relação entre mito, rito e símbolo nas práticas celebrativas de diferentes tradições religiosas.', '6º ano(s) do Ensino Fundamental', 'Ensino Religioso'),
  ('EF06GE01', 'ef06ge01', 'Comparar modificações das paisagens nos lugares de vivência e os usos desses lugares em diferentes tempos.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE02', 'ef06ge02', 'Analisar modificações de paisagens por diferentes tipos de sociedade, com destaque para os povos originários.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE03', 'ef06ge03', 'Descrever os movimentos do planeta e sua relação com a circulação geral da atmosfera, o tempo atmosférico e os padrões climáticos.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE04', 'ef06ge04', 'Descrever o ciclo da água, comparando o escoamento superficial no ambiente urbano e rural, reconhecendo os principais componentes da morfologia das bacias e das redes hidrográficas e a sua localização no modelado da superfície terrestre e da cobertura vegetal.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE05', 'ef06ge05', 'Relacionar padrões climáticos, tipos de solo, relevo e formações vegetais.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE06', 'ef06ge06', 'Identificar as características das paisagens transformadas pelo trabalho humano a partir do desenvolvimento da agropecuária e do processo de industrialização.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE07', 'ef06ge07', 'Explicar as mudanças na interação humana com a natureza a partir do surgimento das cidades.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE08', 'ef06ge08', 'Medir distâncias na superfície pelas escalas gráficas e numéricas dos mapas.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE09', 'ef06ge09', 'Elaborar modelos tridimensionais, blocos-diagramas e perfis topográficos e de vegetação, visando à representação de elementos e estruturas da superfície terrestre.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE10', 'ef06ge10', 'Explicar as diferentes formas de uso do solo (rotação de terras, terraceamento, aterros etc.) e de apropriação dos recursos hídricos (sistema de irrigação, tratamento e redes de distribuição), bem como suas vantagens e desvantagens em diferentes épocas e lugares.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE11', 'ef06ge11', 'Analisar distintas interações das sociedades com a natureza, com base na distribuição dos componentes físico-naturais, incluindo as transformações da biodiversidade local e do mundo.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE12', 'ef06ge12', 'Identificar o consumo dos recursos hídricos e o uso das principais bacias hidrográficas no Brasil e no mundo, enfatizando as transformações nos ambientes urbanos.', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06GE13', 'ef06ge13', 'Analisar consequências, vantagens e desvantagens das práticas humanas na dinâmica climática (ilha de calor etc.).', '6º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF06HI01', 'ef06hi01', 'Identificar diferentes formas de compreensão da noção de tempo e de periodização dos processos históricos (continuidades e rupturas).', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI02', 'ef06hi02', 'Identificar a gênese da produção do saber histórico e analisar o significado das fontes que originaram determinadas formas de registro em sociedades e épocas distintas.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI03', 'ef06hi03', 'Identificar as hipóteses científicas sobre o surgimento da espécie humana e sua historicidade e analisar os significados dos mitos de fundação.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI04', 'ef06hi04', 'Conhecer as teorias sobre a origem do homem americano.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI05', 'ef06hi05', 'Descrever modificações da natureza e da paisagem realizadas por diferentes tipos de sociedade, com destaque para os povos indígenas originários e povos africanos, e discutir a natureza e a lógica das transformações ocorridas.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI06', 'ef06hi06', 'Identificar geograficamente as rotas de povoamento no território americano.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI07', 'ef06hi07', 'Identificar aspectos e formas de registro das sociedades antigas na África, no Oriente Médio e nas Américas, distinguindo alguns significados presentes na cultura material e na tradição oral dessas sociedades.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI08', 'ef06hi08', 'Identificar os espaços territoriais ocupados e os aportes culturais, científicos, sociais e econômicos dos astecas, maias e incas e dos povos indígenas de diversas regiões brasileiras.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI09', 'ef06hi09', 'Discutir o conceito de Antiguidade Clássica, seu alcance e limite na tradição ocidental, assim como os impactos sobre outras sociedades e culturas.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI10', 'ef06hi10', 'Explicar a formação da Grécia Antiga, com ênfase na formação da pólis e nas transformações políticas, sociais e culturais.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI11', 'ef06hi11', 'Caracterizar o processo de formação da Roma Antiga e suas configurações sociais e políticas nos períodos monárquico e republicano.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI12', 'ef06hi12', 'Associar o conceito de cidadania a dinâmicas de inclusão e exclusão na Grécia e Roma antigas.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI13', 'ef06hi13', 'Conceituar “império” no mundo antigo, com vistas à análise das diferentes formas de equilíbrio e desequilíbrio entre as partes envolvidas.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI14', 'ef06hi14', 'Identificar e analisar diferentes formas de contato, adaptação ou exclusão entre populações em diferentes tempos e espaços.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI15', 'ef06hi15', 'Descrever as dinâmicas de circulação de pessoas, produtos e culturas no Mediterrâneo e seu significado.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI16', 'ef06hi16', 'Caracterizar e comparar as dinâmicas de abastecimento e as formas de organização do trabalho e da vida social em diferentes sociedades e períodos, com destaque para as relações entre senhores e servos.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI17', 'ef06hi17', 'Diferenciar escravidão, servidão e trabalho livre no mundo antigo.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI18', 'ef06hi18', 'Analisar o papel da religião cristã na cultura e nos modos de organização social no período medieval.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06HI19', 'ef06hi19', 'Descrever e analisar os diferentes papéis sociais das mulheres no mundo antigo e nas sociedades medievais.', '6º ano(s) do Ensino Fundamental', 'História'),
  ('EF06LI01', 'ef06li01', 'Interagir em situações de intercâmbio oral, demonstrando iniciativa para utilizar a língua inglesa.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI02', 'ef06li02', 'Coletar informações do grupo, perguntando e respondendo sobre a família, os amigos, a escola e a comunidade..', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI03', 'ef06li03', 'Solicitar esclarecimentos em língua inglesa sobre o que não entendeu e o significado de palavras ou expressões desconhecidas.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI04', 'ef06li04', 'Reconhecer, com o apoio de palavras cognatas e pistas do contexto discursivo, o assunto e as informações principais em textos orais sobre temas familiares.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI05', 'ef06li05', 'Aplicar os conhecimentos da língua inglesa para falar de si e de outras pessoas, explicitando informações pessoais e características relacionadas a gostos, preferências e rotinas.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI06', 'ef06li06', 'Planejar apresentação sobre a família, a comunidade e a escola, compartilhando-a oralmente com o grupo.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI07', 'ef06li07', 'Formular hipóteses sobre a finalidade de um texto em língua inglesa, com base em sua estrutura, organização textual e pistas gráficas.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI08', 'ef06li08', 'Identificar o assunto de um texto, reconhecendo sua organização textual e palavras cognatas.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI09', 'ef06li09', 'Localizar informações específicas em texto.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI10', 'ef06li10', 'Conhecer a organização de um dicionário bilíngue (impresso e/ou on-line) para construir repertório lexical.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI11', 'ef06li11', 'Explorar ambientes virtuais e/ou aplicativos para construir repertório lexical na língua inglesa.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI12', 'ef06li12', 'Interessar-se pelo texto lido, compartilhando suas ideias sobre o que o texto informa/comunica.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI13', 'ef06li13', 'Listar ideias para a produção de textos, levando em conta o tema e o assunto.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI14', 'ef06li14', 'Organizar ideias, selecionando-as em função da estrutura e do objetivo do texto.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI15', 'ef06li15', 'Produzir textos escritos em língua inglesa (histórias em quadrinhos, cartazes, chats, blogues, agendas, fotolegendas, entre outros), sobre si mesmo, sua família, seus amigos, gostos, preferências e rotinas, sua comunidade e seu contexto escolar.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI16', 'ef06li16', 'Construir repertório relativo às expressões usadas para o convívio social e o uso da língua inglesa em sala de aula.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI17', 'ef06li17', 'Construir repertório lexical relativo a temas familiares (escola, família, rotina diária, atividades de lazer, esportes, entre outros).', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI18', 'ef06li18', 'Reconhecer semelhanças e diferenças na pronúncia de palavras da língua inglesa e da língua materna e/ou outras línguas conhecidas.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI19', 'ef06li19', 'Utilizar o presente do indicativo para identificar pessoas (verbo to be) e descrever rotinas diárias.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI20', 'ef06li20', 'Utilizar o presente contínuo para descrever ações em progresso.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI21', 'ef06li21', 'Reconhecer o uso do imperativo em enunciados de atividades, comandos e instruções.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI22', 'ef06li22', 'Descrever relações por meio do uso de apóstrofo (’) + s.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI23', 'ef06li23', 'Empregar, de forma inteligível, os adjetivos possessivos.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI24', 'ef06li24', 'Investigar o alcance da língua inglesa no mundo: como língua materna e/ou oficial (primeira ou segunda língua).', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI25', 'ef06li25', 'Identificar a presença da língua inglesa na sociedade brasileira/comunidade (palavras, expressões, suportes e esferas de circulação e consumo) e seu significado.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LI26', 'ef06li26', 'Avaliar, problematizando elementos/produtos culturais de países de língua inglesa absorvidos pela sociedade brasileira/comunidade.', '6º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF06LP01', 'ef06lp01', 'Reconhecer a impossibilidade de uma neutralidade absoluta no relato de fatos e identificar diferentes graus de parcialidade/ imparcialidade dados pelo recorte feito e pelos efeitos de sentido advindos de escolhas feitas pelo autor, de forma a poder desenvolver uma atitude crítica frente aos textos jornalísticos e tornar-se consciente das escolhas feitas enquanto produtor de textos.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP02', 'ef06lp02', 'Estabelecer relação entre os diferentes gêneros jornalísticos, compreendendo a centralidade da notícia.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP03', 'ef06lp03', 'Analisar diferenças de sentido entre palavras de uma série sinonímica.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP04', 'ef06lp04', 'Analisar a função e as flexões de substantivos e adjetivos e de verbos nos modos Indicativo, Subjuntivo e Imperativo: afirmativo e negativo.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP05', 'ef06lp05', 'Identificar os efeitos de sentido dos modos verbais, considerando o gênero textual e a intenção comunicativa.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP06', 'ef06lp06', 'Empregar, adequadamente, as regras de concordância nominal (relações entre os substantivos e seus determinantes) e as regras de concordância verbal (relações entre o verbo e o sujeito simples e composto).', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP07', 'ef06lp07', 'Identificar, em textos, períodos compostos por orações separadas por vírgula sem a utilização de conectivos, nomeando-os como períodos compostos por coordenação.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP08', 'ef06lp08', 'Identificar, em texto ou sequência textual, orações como unidades constituídas em torno de um núcleo verbal e períodos como conjunto de orações conectadas.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP09', 'ef06lp09', 'Classificar, em texto ou sequência textual, os períodos simples compostos.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP10', 'ef06lp10', 'Identificar sintagmas nominais e verbais como constituintes imediatos da oração.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP11', 'ef06lp11', 'Utilizar, ao produzir texto, conhecimentos linguísticos e gramaticais: tempos verbais, concordância nominal e verbal, regras ortográficas, pontuação etc.', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06LP12', 'ef06lp12', 'Utilizar, ao produzir texto, recursos de coesão referencial (nome e pronomes), recursos semânticos de sinonímia, antonímia e homonímia e mecanismos de representação de diferentes vozes (discurso direto e indireto).', '6º ano(s) do Ensino Fundamental', 'Língua Portuguesa'),
  ('EF06MA01', 'ef06ma01', 'Comparar, ordenar, ler e escrever números naturais e números racionais cuja representação decimal é finita, fazendo uso da reta numérica.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA02', 'ef06ma02', 'Reconhecer o sistema de numeração decimal, como o que prevaleceu no mundo ocidental, e destacar semelhanças e diferenças com outros sistemas, de modo a sistematizar suas principais características (base, valor posicional e função do zero), utilizando, inclusive, a composição e decomposição de números naturais e números racionais em sua representação decimal.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA03', 'ef06ma03', 'Resolver e elaborar problemas que envolvam cálculos (mentais ou escritos, exatos ou aproximados) com números naturais, por meio de estratégias variadas, com compreensão dos processos neles envolvidos com e sem uso de calculadora.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA04', 'ef06ma04', 'Construir algoritmo em linguagem natural e representá-lo por fluxograma que indique a resolução de um problema simples (por exemplo, se um número natural qualquer é par).', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA05', 'ef06ma05', 'Classificar números naturais em primos e compostos, estabelecer relações entre números, expressas pelos termos “é múltiplo de”, “é divisor de”, “é fator de”, e estabelecer, por meio de investigações, critérios de divisibilidade por 2, 3, 4, 5, 6, 8, 9, 10, 100 e 1000.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA06', 'ef06ma06', 'Resolver e elaborar problemas que envolvam as ideias de múltiplo e de divisor.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA07', 'ef06ma07', 'Compreender, comparar e ordenar frações associadas às ideias de partes de inteiros e resultado de divisão, identificando frações equivalentes.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA08', 'ef06ma08', 'Reconhecer que os números racionais positivos podem ser expressos nas formas fracionária e decimal, estabelecer relações entre essas representações, passando de uma representação para outra, e relacioná-los a pontos na reta numérica.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA09', 'ef06ma09', 'Resolver e elaborar problemas que envolvam o cálculo da fração de uma quantidade e cujo resultado seja um número natural, com e sem uso de calculadora.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA10', 'ef06ma10', 'Resolver e elaborar problemas que envolvam adição ou subtração com números racionais positivos na representação fracionária.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA11', 'ef06ma11', 'Resolver e elaborar problemas com números racionais positivos na representação decimal, envolvendo as quatro operações fundamentais e a potenciação, por meio de estratégias diversas, utilizando estimativas e arredondamentos para verificar a razoabilidade de respostas, com e sem uso de calculadora.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA12', 'ef06ma12', 'Fazer estimativas de quantidades e aproximar números para múltiplos da potência de 10 mais próxima.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA13', 'ef06ma13', 'Resolver e elaborar problemas que envolvam porcentagens, com base na ideia de proporcionalidade, sem fazer uso da “regra de três”, utilizando estratégias pessoais, cálculo mental e calculadora, em contextos de educação financeira, entre outros.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA14', 'ef06ma14', 'Reconhecer que a relação de igualdade matemática não se altera ao adicionar, subtrair, multiplicar ou dividir os seus dois membros por um mesmo número e utilizar essa noção para determinar valores desconhecidos na resolução de problemas.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA15', 'ef06ma15', 'Resolver e elaborar problemas que envolvam a partilha de uma quantidade em duas partes desiguais, envolvendo relações aditivas e multiplicativas, bem como a razão entre as partes e entre uma das partes e o todo.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA16', 'ef06ma16', 'Associar pares ordenados de números a pontos do plano cartesiano do 1º quadrante, em situações como a localização dos vértices de um polígono.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA17', 'ef06ma17', 'Quantificar e estabelecer relações entre o número de vértices, faces e arestas de prismas e pirâmides, em função do seu polígono da base, para resolver problemas e desenvolver a percepção espacial.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA18', 'ef06ma18', 'Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e classificá-los em regulares e não regulares, tanto em suas representações no plano como em faces de poliedros.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA19', 'ef06ma19', 'Identificar características dos triângulos e classificá-los em relação às medidas dos lados e dos ângulos.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA20', 'ef06ma20', 'Identificar características dos quadriláteros, classificá-los em relação a lados e a ângulos e reconhecer a inclusão e a intersecção de classes entre eles.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA21', 'ef06ma21', 'Construir figuras planas semelhantes em situações de ampliação e de redução, com o uso de malhas quadriculadas, plano cartesiano ou tecnologias digitais.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA22', 'ef06ma22', 'Utilizar instrumentos, como réguas e esquadros, ou softwares para representações de retas paralelas e perpendiculares e construção de quadriláteros, entre outros.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA23', 'ef06ma23', 'Construir algoritmo para resolver situações passo a passo (como na construção de dobraduras ou na indicação de deslocamento de um objeto no plano segundo pontos de referência e distâncias fornecidas etc.).', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA24', 'ef06ma24', 'Resolver e elaborar problemas que envolvam as grandezas comprimento, massa, tempo, temperatura, área (triângulos e retângulos), capacidade e volume (sólidos formados por blocos retangulares), sem uso de fórmulas, inseridos, sempre que possível, em contextos oriundos de situações reais e/ou relacionadas às outras áreas do conhecimento.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA25', 'ef06ma25', 'Reconhecer a abertura do ângulo como grandeza associada às figuras geométricas.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA26', 'ef06ma26', 'Resolver problemas que envolvam a noção de ângulo em diferentes contextos e em situações reais, como ângulo de visão.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA27', 'ef06ma27', 'Determinar medidas da abertura de ângulos, por meio de transferidor e/ou tecnologias digitais.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA28', 'ef06ma28', 'Interpretar, descrever e desenhar plantas baixas simples de residências e vistas aéreas.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA29', 'ef06ma29', 'Analisar e descrever mudanças que ocorrem no perímetro e na área de um quadrado ao se ampliarem ou reduzirem, igualmente, as medidas de seus lados, para compreender que o perímetro é proporcional à medida do lado, o que não ocorre com a área.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA30', 'ef06ma30', 'Calcular a probabilidade de um evento aleatório, expressando-a por número racional (forma fracionária, decimal e percentual) e comparar esse número com a probabilidade obtida por meio de experimentos sucessivos.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA31', 'ef06ma31', 'Identificar as variáveis e suas frequências e os elementos constitutivos (título, eixos, legendas, fontes e datas) em diferentes tipos de gráfico.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA32', 'ef06ma32', 'Interpretar e resolver situações que envolvam dados de pesquisas sobre contextos ambientais, sustentabilidade, trânsito, consumo responsável, entre outros, apresentadas pela mídia em tabelas e em diferentes tipos de gráficos e redigir textos escritos com o objetivo de sintetizar conclusões.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA33', 'ef06ma33', 'Planejar e coletar dados de pesquisa referente a práticas sociais escolhidas pelos alunos e fazer uso de planilhas eletrônicas para registro, representação e interpretação das informações, em tabelas, vários tipos de gráficos e texto.', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF06MA34', 'ef06ma34', 'Interpretar e desenvolver fluxogramas simples, identificando as relações entre os objetos representados (por exemplo, posição de cidades considerando as estradas que as unem, hierarquia dos funcionários de uma empresa etc.).', '6º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF07CI01', 'ef07ci01', 'Discutir a aplicação, ao longo da história, das máquinas simples e propor soluções e invenções para a realização de tarefas mecânicas cotidianas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI02', 'ef07ci02', 'Diferenciar temperatura, calor e sensação térmica nas diferentes situações de equilíbrio termodinâmico cotidianas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI03', 'ef07ci03', 'Utilizar o conhecimento das formas de propagação do calor para justificar a utilização de determinados materiais (condutores e isolantes) na vida cotidiana, explicar o princípio de funcionamento de alguns equipamentos (garrafa térmica, coletor solar etc.) e/ou construir soluções tecnológicas a partir desse conhecimento.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI04', 'ef07ci04', 'Avaliar o papel do equilíbrio termodinâmico para a manutenção da vida na Terra, para o funcionamento de máquinas térmicas e em outras situações cotidianas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI05', 'ef07ci05', 'Discutir o uso de diferentes tipos de combustível e máquinas térmicas ao longo do tempo, para avaliar avanços, questões econômicas e problemas socioambientais causados pela produção e uso desses materiais e máquinas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI06', 'ef07ci06', 'Discutir e avaliar mudanças econômicas, culturais e sociais, tanto na vida cotidiana quanto no mundo do trabalho, decorrentes do desenvolvimento de novos materiais e tecnologias (como automação e informatização).', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI07', 'ef07ci07', 'Caracterizar os principais ecossistemas brasileiros quanto à paisagem, à quantidade de água, ao tipo de solo, à disponibilidade de luz solar, à temperatura etc., correlacionando essas características à flora e fauna específicas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI08', 'ef07ci08', 'Avaliar como os impactos provocados por catástrofes naturais ou mudanças nos componentes físicos, biológicos ou sociais de um ecossistema afetam suas populações, podendo ameaçar ou provocar a extinção de espécies, alteração de hábitos, migração etc.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI09', 'ef07ci09', 'Interpretar as condições de saúde da comunidade, cidade ou estado, com base na análise e comparação de indicadores de saúde (como taxa de mortalidade infantil, cobertura de saneamento básico e incidência de doenças de veiculação hídrica, atmosférica entre outras) e dos resultados de políticas públicas destinadas à saúde.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI10', 'ef07ci10', 'Argumentar sobre a importância da vacinação para a saúde pública, com base em informações sobre a maneira como a vacina atua no organismo e o papel histórico da vacinação para a manutenção da saúde individual e coletiva e para a erradicação de doenças.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI11', 'ef07ci11', 'Analisar historicamente o uso da tecnologia, incluindo a digital, nas diferentes dimensões da vida humana, considerando indicadores ambientais e de qualidade de vida.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI12', 'ef07ci12', 'Demonstrar que o ar é uma mistura de gases, identificando sua composição, e discutir fenômenos naturais ou antrópicos que podem alterar essa composição.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI13', 'ef07ci13', 'Descrever o mecanismo natural do efeito estufa, seu papel fundamental para o desenvolvimento da vida na Terra, discutir as ações humanas responsáveis pelo seu aumento artificial (queima dos combustíveis fósseis, desmatamento, queimadas etc.) e selecionar e implementar propostas para a reversão ou controle desse quadro.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI14', 'ef07ci14', 'Justificar a importância da camada de ozônio para a vida na Terra, identificando os fatores que aumentam ou diminuem sua presença na atmosfera, e discutir propostas individuais e coletivas para sua preservação.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI15', 'ef07ci15', 'Interpretar fenômenos naturais (como vulcões, terremotos e tsunamis) e justificar a rara ocorrência desses fenômenos no Brasil, com base no modelo das placas tectônicas.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CI16', 'ef07ci16', 'Justificar o formato das costas brasileira e africana com base na teoria da deriva dos continentes.', '7º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF07CO01', 'ef07co01', 'Criar soluções de problemas para os quais seja adequado o uso de registros e matrizes unidimensionais para descrever suas informações e automatizá-las usando uma linguagem de programação.', '7º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF07CO02', 'ef07co02', 'Analisar programas para detectar e remover erros, ampliando a confiança na sua correção.', '7º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
  ('EF07CO03', 'ef07co03', 'Construir soluções computacionais de problemas de diferentes áreas do conhecimento, de forma individual e colaborativa, selecionando as estruturas de dados e técnicas adequadas, aperfeiçoando e articulando saberes escolares.', '7º ano(s) do Ensino Fundamental', 'Computação — Pensamento Computacional'),
