  ('EF07GE09', 'ef07ge09', 'Interpretar e elaborar mapas temáticos e históricos, inclusive utilizando tecnologias digitais, com informações demográficas e econômicas do Brasil (cartogramas), identificando padrões espaciais, regionalizações e analogias espaciais.', '7º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF07GE10', 'ef07ge10', 'Elaborar e interpretar gráficos de barras, gráficos de setores e histogramas, com base em dados socioeconômicos das regiões brasileiras.', '7º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF07GE11', 'ef07ge11', 'Caracterizar dinâmicas dos componentes físico-naturais no território nacional, bem como sua distribuição e biodiversidade (Florestas Tropicais, Cerrados, Caatingas, Campos Sulinos e Matas de Araucária).', '7º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF07GE12', 'ef07ge12', 'Comparar unidades de conservação existentes no Município de residência e em outras localidades brasileiras, com base na organização do Sistema Nacional de Unidades de Conservação (SNUC).', '7º ano(s) do Ensino Fundamental', 'Geografia'),
