  ('EF07MA18', 'ef07ma18', 'Resolver e elaborar problemas que possam ser representados por equações polinomiais de 1º grau, redutíveis à forma ax + b = c, fazendo uso das propriedades da igualdade.', '7º ano(s) do Ensino Fundamental', 'Matemática'),
  ('EF07MA19', 'ef07ma19', 'Realizar transformações de polígonos representados no plano cartesiano, decorrentes da multiplicação das coordenadas de seus vértices por um número inteiro.', '7º ano(s) do Ensino Fundamental', 'Matemática'),
