  ('EF08CI05', 'ef08ci05', 'Propor ações coletivas para otimizar o uso de energia elétrica em sua escola e/ou comunidade, com base na seleção de equipamentos segundo critérios de sustentabilidade (consumo de energia e eficiência energética) e hábitos de consumo responsável.', '8º ano(s) do Ensino Fundamental', 'Ciências'),
  ('EF08CI06', 'ef08ci06', 'Discutir e avaliar usinas de geração de energia elétrica (termelétricas, hidrelétricas, eólicas etc.), suas semelhanças e diferenças, seus impactos socioambientais, e como essa energia chega e é usada em sua cidade, comunidade, casa ou escola.', '8º ano(s) do Ensino Fundamental', 'Ciências'),
