  ('EF08GE14', 'ef08ge14', 'Analisar os processos de desconcentração, descentralização e recentralização das atividades econômicas a partir do capital estadunidense e chinês em diferentes regiões no mundo, com destaque para o Brasil.', '8º ano(s) do Ensino Fundamental', 'Geografia'),
  ('EF08GE15', 'ef08ge15', 'Analisar a importância dos principais recursos hídricos da America Latina (Aquífero Guarani, Bacias do rio da Prata, do Amazonas e do Orinoco, sistemas de nuvens na Amazônia e nos Andes, entre outros) e discutir os desafios relacionados à gestão e comercialização da água.', '8º ano(s) do Ensino Fundamental', 'Geografia'),
