  ('EF08HI27', 'ef08hi27', 'Identificar as tensões e os significados dos discursos civilizatórios, avaliando seus impactos negativos para os povos indígenas originários e as populações negras nas Américas.', '8º ano(s) do Ensino Fundamental', 'História'),
  ('EF08LI01', 'ef08li01', 'Fazer uso da língua inglesa para resolver mal-entendidos, emitir opiniões e esclarecer informações por meio de paráfrases ou justificativas.', '8º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF08LI02', 'ef08li02', 'Explorar o uso de recursos linguísticos (frases incompletas, hesitações, entre outros) e paralinguísticos (gestos, expressões faciais, entre outros) em situações de interação oral.', '8º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
  ('EF08LI03', 'ef08li03', 'Construir o sentido global de textos orais, relacionando suas partes, o assunto principal e informações relevantes.', '8º ano(s) do Ensino Fundamental', 'Língua Inglesa'),
